 "在线工具大全 · 所有工具永久免费 · 更多工具持续上新": "Online Tools · All tools free forever · More tools coming soon",
 "BMI与每日热量计算器 - 在线BMI/基础代谢/减脂热量计算工具 | 在线工具大全": "BMI & Daily Calorie Calculator - Online BMI / BMR / Fat Loss Calorie Tool | 在线工具大全",
 "免费在线BMI与每日热量计算器，输入性别、年龄、身高、体重即可计算BMI（中国与WHO双标准分类）、健康体重范围、理想体重、基础代谢率BMR、每日总热量TDEE，并提供减脂、增肌、维持热量建议与三大营养素搭配方案，全部本地计算。": "Free online BMI and daily calorie calculator. Enter gender, age, height and weight to get your BMI with both Chinese and WHO classifications, healthy weight range, ideal weight, BMR and TDEE, plus cutting, bulking and maintenance calorie targets with macronutrient plans. All computed locally.",
 "BMI与每日热量计算器 - 在线BMI/基础代谢/减脂热量计算工具": "BMI & Daily Calorie Calculator - Online BMI / BMR / Fat Loss Calorie Tool",
 "输入性别年龄身高体重，一键计算BMI双标准分类、健康体重范围、BMR、TDEE与减脂增肌目标热量及三大营养素方案。": "Enter gender, age, height and weight to calculate BMI in two standards, healthy weight range, BMR, TDEE, cutting and bulking calorie targets and macronutrient plans.",
 "BMI与每日热量计算器": "BMI & Daily Calorie Calculator",
 "在线BMI与每日热量计算工具，输入性别、年龄、身高、体重，即可计算BMI（中国与WHO双标准）、健康体重范围、理想体重、基础代谢率与每日总热量，并获得减脂、增肌、维持目标热量与三大营养素搭配建议，全部在浏览器本地完成。": "Online BMI and daily calorie calculator. Enter gender, age, height and weight to get your BMI (Chinese and WHO standards), healthy weight range, ideal weight, BMR and TDEE, plus cutting, bulking and maintenance calorie targets with macronutrient plans, all computed locally in your browser.",
