 "WHO 标准对照：": "WHO standard: ",
 "（偏瘦 &lt;18.5 · 正常 18.5-24.9 · 超重 25-29.9 · 肥胖 ≥30）": "(Underweight &lt;18.5 · Normal 18.5-24.9 · Overweight 25-29.9 · Obese ≥30)",
 "免责声明：本工具的计算结果仅供参考，不构成医疗建议。减脂、增重或存在特殊健康状况时，请咨询专业医生或注册营养师。": "Disclaimer: the results are for reference only and do not constitute medical advice. For weight loss, weight gain or special health conditions, please consult a doctor or a registered dietitian.",
 "常见问题": "Frequently Asked Questions",
 "BMI多少算正常？中国标准和WHO标准有什么区别？": "What BMI is considered normal? What is the difference between the Chinese and WHO standards?",
 "中国标准：BMI小于18.5偏瘦，18.5-23.9正常，24-27.9超重，28及以上肥胖；WHO标准：小于18.5偏瘦，18.5-24.9正常，25-29.9超重，30及以上肥胖。亚洲人群在相同BMI下体脂率往往更高，因此中国标准的上限更低。": "Chinese standard: under 18.5 underweight, 18.5-23.9 normal, 24-27.9 overweight, 28 and above obese. WHO standard: under 18.5 underweight, 18.5-24.9 normal, 25-29.9 overweight, 30 and above obese. Asian populations tend to carry more body fat at the same BMI, so the Chinese standard has a lower upper limit.",
 "BMR和TDEE有什么区别？活动系数怎么选？": "What is the difference between BMR and TDEE? How do I choose the activity factor?",
 "BMR（基础代谢率）是人体安静状态下维持生命所需的最低热量，本工具采用Mifflin-St Jeor公式计算；TDEE（每日总热量消耗）= BMR × 活动系数，反映含日常活动与运动的总消耗。卧床约1.2、轻度活动1.375、中度1.55、高强度1.725、极高强度1.9，可按每周运动频率选择最接近的一档。": "BMR (basal metabolic rate) is the minimum energy needed to sustain life at rest, calculated here with the Mifflin-St Jeor equation. TDEE (total daily energy expenditure) = BMR × activity factor, reflecting total burn including daily activity and exercise. Bedridden is about 1.2, lightly active 1.375, moderately active 1.55, very active 1.725 and extremely active 1.9; pick the level closest to your weekly exercise frequency.",
 "减脂建议每天少摄入500千卡安全吗？": "Is it safe to eat 500 kcal less per day for fat loss?",
 "在TDEE基础上减少500千卡约对应每周减重0.5公斤，属于温和可持续的速度；增肌建议在TDEE基础上增加300千卡并配合抗阻训练。个人差异较大，孕妇、青少年及慢性病患者应在专业人士指导下调整。": "A 500 kcal deficit below TDEE corresponds to losing about 0.5 kg per week, a moderate and sustainable pace. For muscle gain, add 300 kcal above TDEE and pair it with resistance training. Individual results vary; pregnant women, teenagers and people with chronic conditions should adjust under professional guidance.",
