 "日历工具 - 在线日历查询/节假日安排/倒计时工具 | 在线工具大全": "Calendar Tool - Online Calendar, Holiday Schedule & Countdown | 在线工具大全",
 "免费在线日历工具，支持月视图浏览、今天高亮、周一/周日起始切换，内置2024-2027年中国法定节假日与调休上班日数据，提供日期详情、本月工作日统计与下一个节假日倒计时，全部本地运行。": "Free online calendar tool with month view, today highlighting and Sunday/Monday week start switching. Built-in 2024-2027 Chinese public holiday and makeup workday data, date details, monthly workday statistics and a countdown to the next holiday. Runs entirely locally.",
 "日历工具 - 在线日历查询/节假日安排/倒计时工具": "Calendar Tool - Online Calendar, Holiday Schedule & Countdown",
 "在线日历查询工具，内置2024-2027年法定节假日与调休数据，支持月视图、日期详情、本月统计与节假日倒计时。": "Online calendar tool with built-in 2024-2027 public holiday and makeup workday data, month view, date details, monthly statistics and a holiday countdown.",
 "日历工具": "Calendar Tool",
 "在线日历查询工具，支持月视图浏览、今天高亮、周一/周日起始切换，内置 2024-2027 年中国法定节假日放假安排与调休上班日数据，提供日期详情、本月工作日统计与下一个节假日倒计时，全部本地运行。": "Online calendar tool with month view, today highlighting and Sunday/Monday week start switching. Built-in 2024-2027 Chinese public holiday arrangements and makeup workday data, date details, monthly workday statistics and a countdown to the next holiday. Runs entirely locally.",
