 "键盘快捷键：按 ◀ / ▶ 方向键切换上月、下月，按 T 键回到今天；输入框或下拉列表聚焦时快捷键不生效。节假日数据来源于国务院办公厅发布的年度放假安排，2028 年及以后暂无数据。": "Keyboard shortcuts: press ◀ / ▶ to switch to the previous or next month, and T to return to today. Shortcuts are inactive while an input or dropdown is focused. Holiday data comes from the State Council's annual holiday arrangements; data for 2028 and later is not yet available.",
 "日历工具支持哪些年份的节假日数据？": "Which years of holiday data does the calendar tool support?",
 "已内置2024年至2027年的中国法定节假日放假安排，含元旦、春节、清明节、劳动节、端午节、中秋节、国庆节的放假日期与调休上班日。2028年及以后的日期会正常显示日历，但没有节假日标识，待官方通知发布后可补充数据。": "Public holiday arrangements for 2024 to 2027 are built in, covering New Year's Day, Spring Festival, Qingming Festival, Labour Day, Dragon Boat Festival, Mid-Autumn Festival and National Day, including holiday dates and makeup workdays. Dates from 2028 onward display normally but without holiday labels, until data can be added once official notices are published.",
 "本月统计里的工作日和节假日是怎么算的？": "How are workdays and holidays counted in the monthly statistics?",
 "工作日指周一到周五且不在放假范围内的日期，加上被标记为调休上班的周末日期；节假日指处于法定放假区间内的日期，可能与周末重叠；周末数指周六和周日的天数。三者之和可能大于本月总天数，因为节假日与周末存在重叠。": "Workdays are Monday to Friday dates outside holiday ranges, plus weekend dates marked as makeup workdays. Holidays are dates within official holiday ranges and may overlap with weekends. Weekends are Saturdays and Sundays. The three counts can add up to more than the days in the month because holidays and weekends overlap.",
 "键盘快捷键有哪些？": "What keyboard shortcuts are available?",
 "在页面空白处聚焦时（输入框聚焦时快捷键不生效），按左方向键 ◀ 切换上一个月，按右方向键 ▶ 切换下一个月，按字母 T 快速回到今天所在的月份并选中今天。": "When the page body has focus (shortcuts are inactive while an input is focused), press the left arrow ◀ for the previous month, the right arrow ▶ for the next month, and the letter T to jump back to the current month with today selected.",
