 "Cron表达式解析器 - 在线Cron表达式解析与执行时间预测工具 | 在线工具大全": "Cron Expression Parser - Online Cron Parser & Next Run Time Predictor | 在线工具大全",
 "免费在线Cron表达式解析器，支持5位标准与6位带秒表达式、@yearly等特殊宏、L/W/#等高级语法，实时生成中文人类可读描述、字段分解与接下来10次执行时间，全部本地计算，无需注册。": "Free online Cron expression parser supporting 5-field standard and 6-field with-seconds expressions, special macros like @yearly, and L/W/# advanced syntax. It generates human-readable descriptions, field breakdowns and the next 10 run times, all computed locally with no sign-up.",
 "Cron表达式解析器 - 在线Cron解析与执行时间预测工具": "Cron Expression Parser - Online Cron Parser & Next Run Time Predictor",
 "支持5位与6位Cron表达式、特殊宏与高级语法的在线解析器，实时生成中文描述、字段分解与下次执行时间，本地计算。": "Online parser for 5-field and 6-field Cron expressions, special macros and advanced syntax, with human-readable descriptions, field breakdowns and next run times, computed locally.",
 "在线Cron表达式解析工具，支持5位标准与6位带秒表达式、@yearly 等特殊宏、L/W/# 高级语法，实时生成中文人类可读描述、字段分解表与接下来10次执行时间，所有计算均在浏览器本地完成。": "Online Cron expression parser supporting 5-field standard and 6-field with-seconds expressions, special macros such as @yearly, and L/W/# advanced syntax. It generates human-readable descriptions, a field breakdown table and the next 10 run times in real time, all computed locally in your browser.",
