 "所有解析均在浏览器本地完成。": "All parsing is done locally in your browser.",
 "支持 5 位标准表达式（分 时 日 月 周）与 6 位带秒表达式；? 在日/星期字段等价于 *；日字段支持 L（月末）、W（最近工作日），星期字段支持 5#2（每月第二个周五）写法；@reboot 仅作提示，不做精确解析。": "Supports 5-field standard expressions (minute hour day month weekday) and 6-field with-seconds expressions; ? is equivalent to * in the day and weekday fields; the day field supports L (last day of month) and W (nearest weekday), and the weekday field supports 5#2 (the second Friday of the month); @reboot is informational only and is not parsed precisely.",
 "Cron 表达式的五个字段分别表示什么？": "What do the five fields of a Cron expression mean?",
 "标准 Cron 表达式由 5 个字段组成，依次为分钟（0-59）、小时（0-23）、日（1-31）、月（1-12）、星期（0-7，0 和 7 都表示周日），字段之间用空格分隔。本工具同时支持 6 位带秒写法，即在最前面增加秒字段（0-59）。": "A standard Cron expression has 5 fields: minute (0-59), hour (0-23), day of month (1-31), month (1-12) and day of week (0-7, where both 0 and 7 mean Sunday), separated by spaces. This tool also supports a 6-field form that adds a seconds field (0-59) at the front.",
 "工具支持哪些特殊语法？": "What special syntax is supported?",
 "支持 *、数字、a-b 范围、*/n 与 a-b/n 步长、a,b,c 列表、月份名 JAN-DEC、星期名 SUN-SAT；日字段支持 ?、L（月末）、W（最近工作日），星期字段支持 5#2（每月第二个周五）写法；还支持 @yearly、@monthly、@weekly、@daily、@hourly、@reboot 等特殊宏，其中 @reboot 仅作提示，不做精确解析。": "Supported: *, numbers, a-b ranges, */n and a-b/n steps, a,b,c lists, month names JAN-DEC and weekday names SUN-SAT; the day field supports ?, L (last day of month) and W (nearest weekday), and the weekday field supports 5#2 (the second Friday of the month); the special macros @yearly, @monthly, @weekly, @daily, @hourly and @reboot are also supported, where @reboot is informational only and is not parsed precisely.",
 "下次执行时间是如何计算出来的？": "How are the next run times calculated?",
 "从当前时间开始，按天推进并匹配月、日、星期条件，再按小时、分钟（含秒）组合生成候选时间，最多向后搜索 4 年，列出接下来 10 次执行。所有计算均在浏览器本地完成，表达式不会上传。": "Starting from the current time, the tool advances day by day and matches the month, day and weekday conditions, then combines hours, minutes (and seconds) into candidate times, searching up to 4 years ahead to list the next 10 runs. All computation is done locally in your browser and the expression is never uploaded.",
 "在线Cron表达式解析器，支持5位标准与6位带秒表达式、特殊宏与L/W/#高级语法，生成中文描述、字段分解与下次执行时间。": "Online Cron expression parser supporting 5-field standard and 6-field with-seconds expressions, special macros and L/W/# advanced syntax, with descriptions, field breakdowns and next run times.",
