 "EXIF查看器 - 在线照片EXIF信息与GPS位置查看工具 | 在线工具大全": "EXIF Viewer - Online Photo EXIF Info and GPS Location Viewer | Online Tools",
 "免费在线EXIF查看器，上传JPEG照片即可查看相机品牌、型号、拍摄时间、曝光参数、ISO感光度、焦距与GPS位置等全部EXIF信息，支持一键清除隐私数据后下载，100%本地处理，照片不上传。": "Free online EXIF viewer. Upload a JPEG photo to view all EXIF information including camera make, model, capture time, exposure settings, ISO, focal length and GPS location, with one-click privacy clearing before download. 100% local processing, photos are never uploaded.",
 "EXIF查看器 - 在线照片EXIF信息与GPS位置查看工具": "EXIF Viewer - Online Photo EXIF Info and GPS Location Viewer",
 "上传JPEG照片，查看相机参数、拍摄时间与GPS位置等全部EXIF信息，可清除隐私数据后下载，全部在浏览器本地完成。": "Upload a JPEG photo to view camera settings, capture time, GPS location and all other EXIF info, with privacy clearing before download, all in your browser.",
 "在线照片EXIF信息查看工具，上传JPEG照片即可查看相机品牌、型号、拍摄时间、曝光参数与GPS位置等全部元数据，支持清除隐私信息后下载。所有处理均在浏览器本地完成。": "Online photo EXIF viewer. Upload a JPEG photo to check camera make, model, capture time, exposure settings and GPS location metadata, and download a privacy-cleaned copy. Everything is processed locally in your browser.",
 "拖拽 JPEG 照片到此处，或点击选择文件": "Drag and drop a JPEG photo here, or click to choose a file",
