 "清除后的照片预览": "Preview of the cleaned photo",
 "说明：100% 本地处理，照片不上传。EXIF 解析、GPS 换算与隐私清除均在你的浏览器中完成，可离线使用。": "Note: 100% local processing, photos are never uploaded. EXIF parsing, GPS conversion and privacy clearing all happen in your browser and work offline.",
 "EXIF 信息会泄露隐私吗？": "Can EXIF information leak privacy?",
 "会。JPEG 照片的 EXIF 可能包含 GPS 精确位置、拍摄时间与设备型号等信息，直接分享原图可能暴露行踪与设备信息。建议分享前使用本工具清除位置、时间与设备信息。": "Yes. A JPEG photo's EXIF may contain precise GPS location, capture time and device model. Sharing the original file directly can expose your whereabouts and device details. Consider clearing location, time and device information with this tool before sharing.",
 "为什么提示未检测到 EXIF 信息？": "Why does it say no EXIF information was detected?",
 "可能原因有三：文件不是 JPEG 格式（PNG、WebP 等不含 EXIF）；照片经过截图、编辑软件导出或社交媒体压缩，元数据已被移除；拍摄设备关闭了位置信息记录。": "There are three possible reasons: the file is not in JPEG format (PNG and WebP contain no EXIF); the photo was screenshotted, exported from an editor or compressed by social media, which removes metadata; or the device had location recording turned off.",
 "清除 EXIF 后的照片还能正常查看吗？": "Can I still view a photo after clearing EXIF?",
 "可以。清除操作只移除元数据段，不改变照片的像素内容，画面质量、尺寸与格式均不受影响，可正常查看、打印与分享。": "Yes. Clearing only removes the metadata segment and does not change the pixel content, so image quality, dimensions and format are all unaffected. The photo can be viewed, printed and shared normally.",
