 "Favicon生成器 - 在线多尺寸Favicon.ico与PNG图标生成工具 | 在线工具大全": "Favicon Generator - Multi-size Favicon.ico and PNG Icon Generator | Online Tools",
 "免费在线Favicon生成器，上传一张图片即可生成16/32/48/64/128/180/192/512多尺寸PNG图标、favicon.ico、apple-touch-icon与manifest.json，一键打包ZIP下载，全部本地生成，图片不上传。": "Free online favicon generator. Upload one image to generate 16/32/48/64/128/180/192/512 multi-size PNG icons, favicon.ico, apple-touch-icon and manifest.json, then download everything as a ZIP. All generated locally, images are never uploaded.",
 "Favicon生成器 - 在线多尺寸Favicon.ico与PNG图标生成工具": "Favicon Generator - Multi-size Favicon.ico and PNG Icon Generator",
 "上传一张图片，自动生成多尺寸PNG、favicon.ico、apple-touch-icon与manifest.json，可打包ZIP下载，全部在浏览器本地完成。": "Upload one image to auto-generate multi-size PNGs, favicon.ico, apple-touch-icon and manifest.json, packaged as a ZIP download, all in your browser.",
 "在线Favicon与网站图标生成工具，上传一张图片即可生成 16/32/48/64/128/180/192/512 多尺寸 PNG 图标、favicon.ico、apple-touch-icon 与 manifest.json，并可一键打包下载。所有处理均在浏览器本地完成。": "Online favicon and website icon generator. Upload a single image to create 16/32/48/64/128/180/192/512 multi-size PNG icons, favicon.ico, apple-touch-icon and manifest.json, all downloadable in one ZIP. Everything runs locally in your browser.",
 "拖拽图片到此处，或点击选择文件": "Drag and drop an image here, or click to choose a file",
