 "复制 HTML 代码": "Copy HTML Code",
 "打包下载 ZIP": "Download ZIP Package",
 "说明：全部处理均在浏览器本地完成，图片不会上传到任何服务器。favicon.ico 内嵌 PNG 数据，兼容现代浏览器；ZIP 包为无压缩 STORE 格式，可直接解压使用。": "Note: everything is processed locally in your browser and images are never uploaded. favicon.ico embeds PNG data and works in all modern browsers; the ZIP is an uncompressed STORE archive that can be extracted directly.",
 "生成的 favicon.ico 为什么内嵌 PNG 数据？": "Why does the generated favicon.ico embed PNG data?",
 "ICO 容器允许内嵌 PNG 图像，现代浏览器均可正常解析。相比传统 BMP 位图，PNG 压缩率更高、支持透明通道与抗锯齿，因此本工具将 16×16、32×32、48×48 三个尺寸的 PNG 合成为同一个 favicon.ico，兼顾画质与兼容性。": "The ICO container allows embedded PNG images, which all modern browsers can parse. Compared with traditional BMP bitmaps, PNG offers better compression, an alpha channel and anti-aliasing, so this tool packs 16x16, 32x32 and 48x48 PNGs into a single favicon.ico for both quality and compatibility.",
 "上传的图片会上传到服务器吗？": "Will my uploaded image be sent to a server?",
 "不会。图片读取、缩放绘制、图标生成与 ZIP 打包全部在浏览器本地完成，不发起任何网络请求，离线状态下也能正常使用。": "No. Image reading, scaling, icon rendering and ZIP packaging all happen locally in your browser with no network requests, so it works offline too.",
 "生成的图标如何用到网站上？": "How do I use the generated icons on my website?",
 "将 favicon.ico、apple-touch-icon.png、icon-192.png、icon-512.png 与 manifest.json 放到网站根目录，再把工具生成的 HTML 代码复制到页面 &lt;head&gt; 中即可。manifest.json 中的 name、short_name、theme_color、background_color 均按你填写的参数生成。": "Put favicon.ico, apple-touch-icon.png, icon-192.png, icon-512.png and manifest.json in your website root directory, then copy the generated HTML code into the &lt;head&gt; section of your pages. The name, short_name, theme_color and background_color in manifest.json are filled in from the values you enter.",
