 "JSON/YAML/TOML转换 - 在线JSON转YAML/TOML互转工具 | 在线工具大全": "JSON/YAML/TOML Converter - Online JSON to YAML/TOML Tool | 在线工具大全",
 "免费在线JSON/YAML/TOML转换工具，支持JSON转YAML、JSON转TOML、YAML转JSON、YAML转TOML、TOML转JSON、TOML转YAML六种方向，自动识别粘贴格式，错误提示带行号，全部在浏览器本地完成，数据不上传。": "Free online JSON/YAML/TOML converter supporting six directions: JSON to YAML, JSON to TOML, YAML to JSON, YAML to TOML, TOML to JSON and TOML to YAML. It auto-detects pasted formats, reports errors with line numbers, and runs entirely in your browser with no upload.",
 "JSON/YAML/TOML转换 - 在线格式互转工具": "JSON/YAML/TOML Converter - Online Format Conversion Tool",
 "支持JSON、YAML、TOML六种互转方向的在线工具，自动识别格式、错误带行号，本地转换不上传。": "Online tool for converting between JSON, YAML and TOML in six directions, with format auto-detection, line-numbered errors and local conversion without upload.",
 "JSON/YAML/TOML 转换": "JSON/YAML/TOML Converter",
 "在线 JSON、YAML、TOML 互转工具，支持 JSON 转 YAML、JSON 转 TOML、YAML 转 JSON、YAML 转 TOML、TOML 转 JSON、TOML 转 YAML 六种方向，自动识别粘贴内容格式，错误提示带行号，所有转换均在浏览器本地完成。": "Online converter between JSON, YAML and TOML, supporting JSON to YAML, JSON to TOML, YAML to JSON, YAML to TOML, TOML to JSON and TOML to YAML. It auto-detects pasted content, reports errors with line numbers, and performs all conversions locally in your browser.",
