 "项目配置（Cargo.toml、pyproject.toml）": "Project configs (Cargo.toml, pyproject.toml)",
 "所有转换均在浏览器本地完成，数据不上传。": "All conversions run locally in your browser and no data is uploaded.",
 "TOML 与 YAML 输出固定为美化格式，JSON 输出可通过「美化输出」切换缩进与压缩；解析失败时会给出字段名、行号等定位信息，方便快速排查。": "TOML and YAML output is always pretty-printed; JSON output can switch between indented and compact via Pretty output. When parsing fails, the field name and line number are shown to help you locate the problem quickly.",
 "三种格式之间转换会丢失数据吗？": "Does converting between the three formats lose data?",
 "JSON、YAML、TOML 都支持字符串、数字、布尔、数组与嵌套对象，常规结构转换不会丢失数据。需要注意：TOML 没有 null 类型，遇到 null 值会报错；TOML 的日期时间会保留为字符串；YAML 的锚点与别名等高级特性在转换中会被展开为普通结构。": "JSON, YAML and TOML all support strings, numbers, booleans, arrays and nested objects, so regular structures convert without data loss. Note that TOML has no null type and reports an error on null values; TOML datetimes are kept as strings; advanced YAML features such as anchors and aliases are expanded into plain structures during conversion.",
 "为什么转换为 TOML 时报 null 错误？": "Why is there a null error when converting to TOML?",
 "TOML 规范本身没有 null 类型，这是为了保持类型系统的确定性。将 JSON 或 YAML 转换为 TOML 时，如果数据中包含 null，工具会明确指出出错的键，请先删除该键，或把值改为空字符串、0 等。": "The TOML specification has no null type, which keeps its type system deterministic. When converting JSON or YAML to TOML, if the data contains null the tool points out the offending key; please remove that key or change its value to an empty string, 0, etc.",
 "转换是在服务器上完成的吗？": "Is the conversion done on a server?",
 "不是。所有解析与生成都在你的浏览器本地完成，页面不会发起任何网络请求，输入内容不会上传到任何服务器，可以安全处理包含敏感信息的配置数据。": "No. All parsing and generation happen locally in your browser. The page makes no network requests and your input is never uploaded to any server, so it is safe for configuration data containing sensitive information.",
 "在线JSON/YAML/TOML互转工具，支持六种转换方向，自动识别粘贴格式，错误提示带行号，全部在浏览器本地完成。": "Online JSON/YAML/TOML converter with six conversion directions, format auto-detection, line-numbered errors, all done locally in your browser.",
