 "数学家": "Mathematician",
 "高校研究员": "University Researcher",
 "技术架构师": "Technical Architect",
 "指挥官": "Commander",
 "天生的领导者，目标感极强，擅长统筹资源、制定战略并推动执行。自信果断，喜欢挑战，在竞争和压力下反而更加兴奋。重视效率和结果，说话直接，有时会忽略他人的感受。不甘平庸，追求影响力和成就，习惯为团队指明方向。": "A natural leader with a strong sense of purpose, good at coordinating resources, setting strategy, and driving execution. Confident and decisive, they enjoy challenges and get more excited under competition and pressure. They value efficiency and results, speak directly, and sometimes overlook others' feelings. Unwilling to be mediocre, they pursue influence and achievement and habitually point the way for their team.",
 "领导力与号召力强": "Strong leadership and charisma",
 "目标明确，执行力强": "Clear goals and strong execution",
 "善于统筹规划和资源分配": "Good at overall planning and resource allocation",
 "自信果敢，敢于拍板": "Confident, decisive, and willing to call the shots",
 "抗压能力强，越挫越勇": "Strong under pressure, undaunted by setbacks",
 "强势独断，不易听取反对意见": "Forceful and domineering, slow to hear objections",
 "说话直接容易伤人": "Blunt speech that easily hurts feelings",
 "对低效的人和事缺乏耐心": "Little patience with inefficient people or things",
 "工作狂倾向，忽视生活平衡": "Workaholic tendency that neglects life balance",
 "情绪管理能力偏弱": "Weak emotional management",
