 "市场战略": "Marketing Strategy",
 "辩论家": "Debater",
 "思维敏捷、能言善辩，喜欢挑战常规和头脑风暴。对新鲜事物充满好奇，善于发现漏洞并提出创新方案。兴趣广泛但持久性不足，容易在规则和重复中感到厌倦。享受智力交锋的过程，是团队里的点子发动机和气氛担当。": "Quick-witted and eloquent, they enjoy challenging conventions and brainstorming. Curious about new things, they are good at spotting loopholes and proposing innovative solutions. Broad interests but limited persistence, they easily tire of rules and repetition. Enjoying intellectual sparring, they are the team's idea engine and mood lifter.",
 "思维敏捷，创意层出不穷": "Agile thinking with endless ideas",
 "表达能力强，善于说服": "Strong expression and persuasion",
 "适应变化，临场发挥出色": "Adapts to change and improvises well",
 "知识面广，融会贯通": "Broad knowledge with integrated insight",
 "乐观幽默，社交能力好": "Optimistic, humorous, and socially skilled",
 "三分钟热度，难以坚持到底": "Short bursts of enthusiasm, hard to see things through",
 "好争辩，容易较真抬杠": "Argumentative and prone to quibbling",
 "轻视常规流程和细节": "Dismissive of routine procedures and details",
 "做事缺乏条理，计划性弱": "Disorganized and weak at planning",
 "容易给人不靠谱的印象": "Easily gives an unreliable impression",
 "市场营销": "Marketing",
