 "投资人": "Investor",
 "提倡者": "Advocate",
 "理想主义与洞察力的结合，善于洞察人心，对意义和价值有执着的追求。外表安静温和，内心却有着坚定的信念和长远的目标。擅长倾听和启发他人，愿意为认定的价值默默付出。对世界的苦难敏感，容易背负过多他人的情绪。": "A blend of idealism and insight, good at reading people and persistent in the pursuit of meaning and values. Quiet and gentle in appearance, they hold firm beliefs and long-term goals inside. Skilled at listening and inspiring others, they willingly give quietly for the values they believe in. Sensitive to the suffering of the world, they easily carry too much of others' emotions.",
 "洞察人心，共情能力强": "Reads people well with strong empathy",
 "有信念感，为理想坚持": "Principled and persistent for ideals",
 "创造力与洞察力兼备": "Combines creativity with insight",
 "善于倾听和鼓舞他人": "Good at listening and encouraging others",
 "做事有深度，不浮于表面": "Works with depth, never superficially",
 "对自己和他人期待过高": "Expects too much of self and others",
 "容易积累负面情绪": "Easily accumulates negative emotions",
 "过度付出导致倦怠": "Overgiving that leads to burnout",
 "冲突面前倾向逃避或内伤": "Tends to avoid conflict or hurt inwardly",
 "理想与现实的落差带来痛苦": "The gap between ideal and reality brings pain",
 "心理咨询师": "Counseling Psychologist",
