 "公益项目负责人": "Nonprofit Program Lead",
 "调停者": "Mediator",
 "温柔的理想主义者，内心世界丰富，重视价值观与真诚。善解人意，总能站在他人角度思考，渴望世界变得更好。讨厌冲突和虚伪，宁愿沉默也不愿违心迎合。有艺术天赋和文字敏感度，适合需要创造力与人文关怀的领域。": "Gentle idealists with a rich inner world who value authenticity. Understanding, they always think from others' perspectives and long for a better world. They hate conflict and hypocrisy and would rather stay silent than hypocritically please. With artistic talent and a feel for words, they suit fields that need creativity and humanistic care.",
 "共情力强，善良体贴": "Empathetic, kind, and considerate",
 "富有创造力与想象力": "Creative and imaginative",
 "忠于自己的价值观": "Loyal to their own values",
 "包容开放，不轻易评判": "Tolerant and open, slow to judge",
 "在热爱的事情上极具热情": "Passionate about the things they love",
 "过于理想化，容易失望": "Overly idealistic and easily disappointed",
 "不擅拒绝，容易受委屈": "Poor at refusing, easily wronged",
 "逃避冲突和现实问题": "Avoids conflict and practical problems",
 "自我怀疑，缺乏自信": "Self-doubting and lacking confidence",
 "容易沉溺于情绪": "Easily immersed in emotions",
 "插画师": "Illustrator",
