 "冷静的实干派，喜欢用双手和工具理解世界。危机面前格外镇定，擅长快速定位问题并动手解决。重视自由和效率，讨厌冗长的会议和空洞的讨论。话不多，但每句都切中要害，对感兴趣的领域钻研极深。": "Calm doers who like to understand the world with their hands and tools. Exceptionally composed in a crisis, they quickly locate problems and fix them. Valuing freedom and efficiency, they hate long meetings and empty discussion. Not talkative, but every word hits the mark, and they dig extremely deep into whatever interests them.",
