 "在左侧输入代码或点击上方示例，预览将在此显示": "Enter code on the left or click an example above, the preview will appear here",
 "在此输入 Mermaid 语法，例如：flowchart TD\nA[开始] --> B{判断}\nB -->|是| C[执行]\nB -->|否| D[结束]": "Enter Mermaid syntax here, e.g. flowchart TD\nA[Start] --> B{Decision}\nB -->|Yes| C[Do]\nB -->|No| D[End]",
 "100% 浏览器本地渲染": "100% rendered locally in your browser",
 "，你输入的内容不会上传到任何服务器。若渲染失败，请检查 Mermaid 语法（如分号、连接符、关键字是否正确），错误信息会显示在上方提示区。": ", your input is never uploaded to any server. If rendering fails, check the Mermaid syntax (e.g. semicolons, connectors, keywords) and the error message will show in the box above.",
 "Mermaid 编辑器需要联网吗？": "Does the Mermaid editor need an internet connection?",
 "不需要。所有图表都在你的浏览器本地使用 Mermaid 库渲染，输入的代码和图表内容不会上传到任何服务器，适合处理内部或敏感流程。": "No. All diagrams are rendered locally in your browser with the Mermaid library. Your code and diagrams are never uploaded to any server, which makes it safe for internal or sensitive workflows.",
 "支持导出哪些格式？": "Which export formats are supported?",
 "支持将当前图表导出为 SVG 矢量图和 PNG 位图。SVG 可无损缩放并继续编辑，PNG 适合直接插入文档或演示稿。": "You can export the current diagram as an SVG vector image or a PNG bitmap. SVG scales without quality loss and stays editable, while PNG is handy for documents and slides.",
 "为什么图表渲染失败？": "Why did the diagram fail to render?",
 "通常是 Mermaid 语法有误，例如缺少分号、节点连接符写错或使用了不支持的关键字。请根据下方错误提示修正对应语法，再点击渲染。": "Usually it is a Mermaid syntax error, such as a missing semicolon, a wrong node connector, or an unsupported keyword. Fix the syntax following the error message below, then click Render.",
 "Mermaid在线编辑器 - 流程图/时序图/类图图表生成 | 在线工具大全": "Mermaid Online Editor - Flowchart/Sequence/Class Diagram Generator | Online Tools Hub",
 "免费在线 Mermaid 编辑器，支持流程图、时序图、类图、ER图、甘特图、思维导图、饼图的实时预览与导出，所有图表均在浏览器本地渲染，内容不上传，无需注册。": "A free online Mermaid editor with live preview and export for flowcharts, sequence diagrams, class diagrams, ER diagrams, Gantt charts, mindmaps and pie charts. Everything renders locally in your browser with no upload and no sign-up.",
 "Mermaid编辑器,Mermaid在线,流程图,时序图,类图,ER图,甘特图,思维导图,饼图,图表生成,Mermaid预览": "Mermaid editor, Mermaid online, flowchart, sequence diagram, class diagram, ER diagram, Gantt chart, mindmap, pie chart, diagram generator, Mermaid preview",
 "Mermaid在线编辑器 - 流程图/时序图/类图图表生成": "Mermaid Online Editor - Flowchart/Sequence/Class Diagram Generator",
 "支持流程图、时序图、类图、ER图、甘特图、思维导图、饼图的实时预览与导出的在线 Mermaid 编辑器。": "An online Mermaid editor with live preview and export for flowcharts, sequence diagrams, class diagrams, ER diagrams, Gantt charts, mindmaps and pie charts.",
 "在线 Mermaid 编辑器，支持流程图、时序图、类图、ER图、甘特图、思维导图、饼图的实时预览与导出，浏览器本地渲染。": "An online Mermaid editor supporting live preview and export of flowcharts, sequence diagrams, class diagrams, ER diagrams, Gantt charts, mindmaps and pie charts, rendered locally in the browser.",
 "实时预览": "Live Preview",
