 "点击按钮开始抛掷": "Click the button to flip",
 "正面 0 次 · 反面 0 次 · 正面比例 0%": "Heads 0 · Tails 0 · Head rate 0%",
 "所有随机过程均在你的浏览器本地完成，不会上传任何数据。真随机使用 Web Crypto，种子模式使用 mulberry32 伪随机算法便于复现。": "All randomness is generated locally in your browser; no data is uploaded. True random uses Web Crypto; seed mode uses the mulberry32 pseudo-random algorithm for reproducibility.",
 "转盘抽奖的结果是公平的吗？": "Is the wheel draw result fair?",
 "是。转盘通过浏览器原生 crypto 随机数从所有条目中等概率抽取一个扇区，每个条目中奖概率完全相同，结果不可预测。开启公平种子模式后会改用确定性算法，便于演示复现。": "Yes. The wheel uses the browser's native crypto random number to pick one sector with equal probability, so every item has the same chance and the result is unpredictable. Enabling fair seed mode switches to a deterministic algorithm for reproducible demos.",
 "公平种子模式有什么用？": "What is fair seed mode for?",
 "输入同样的种子，随机抽取、骰子、抛硬币的结果将完全一致，便于在课堂上演示或复现某次结果。不开启时使用 crypto 真随机，每次结果都不同。": "With the same seed, the results of random draw, dice and coin flip will be identical, which is handy for classroom demos or reproducing a specific result. Without it, true crypto random is used and results differ each time.",
 "随机数生成使用什么算法保证无偏？": "What algorithm ensures unbiased random numbers?",
 "默认使用 Web Crypto 的 crypto.getRandomValues 结合拒绝采样，确保每个整数等概率且分布无偏；开启种子模式后改用 mulberry32 伪随机算法以保证可复现。": "By default it uses Web Crypto's crypto.getRandomValues with rejection sampling, ensuring every integer is equally probable and unbiased; seed mode switches to the mulberry32 pseudo-random algorithm for reproducibility.",
