 "世界时钟与时区转换器 - 在线时区转换/世界时间对照工具 | 在线工具大全": "World Clock & Time Zone Converter - Online Time Zone & World Time Tool | 在线工具大全",
 "免费在线世界时钟与时区转换器，内置北京、东京、伦敦、纽约等常用城市时钟，支持任意时区增减排序、时间转换、一天内时间滑块、UTC-12至UTC+14时区速查与跨时区共同工作时段计算，基于IANA时区数据库本地运行，无需联网。": "Free online world clock and time zone converter with built-in clocks for Beijing, Tokyo, London and New York. Add, remove and reorder any time zone, convert times, scrub through a day, look up UTC-12 to UTC+14 zones and find overlapping work hours. Runs locally on IANA time zone data, no network needed.",
 "世界时钟与时区转换器 - 在线时区转换/世界时间对照工具": "World Clock & Time Zone Converter - Online Time Zone & World Time Tool",
 "内置常用城市世界时钟与时区转换，支持UTC-12至UTC+14速查表、一天内时间滑块与共同工作时段计算，基于IANA时区数据库本地运行。": "World clocks for popular cities plus time zone conversion, a UTC-12 to UTC+14 lookup table, a day-scrub slider and overlapping work-hours calculation, all running locally on IANA time zone data.",
 "世界时钟与时区转换器": "World Clock & Time Zone Converter",
 "在线世界时钟与时区转换工具，内置北京、东京、伦敦、纽约等常用城市时钟，支持任意时区增减与排序、时间转换、一天内时间滑块、UTC-12 至 UTC+14 时区速查及跨时区共同工作时段计算，全部基于浏览器本地时区数据完成。": "Online world clock and time zone converter with built-in clocks for Beijing, Tokyo, London and New York. Add, remove and reorder any time zone, convert times, scrub through a day, look up UTC-12 to UTC+14 zones and find overlapping work hours, all computed locally from your browser's time zone data.",
 "默认展示常用城市时钟，每秒自动刷新；可从下拉列表添加更多时区，拖动时间滑块可查看一天内任意时刻的各时区时间。": "Popular city clocks are shown by default and refresh every second. Add more zones from the dropdowns, or drag the time slider to see every zone at any moment of the day.",
 "常用城市": "Popular Cities",
