 "A 工作结束": "A Work End",
 "B 工作开始": "B Work Start",
 "B 工作结束": "B Work End",
 "计算重叠时段": "Calculate Overlap",
 "说明：所有时间均基于浏览器内置的 Intl.DateTimeFormat 与 IANA 时区数据库计算，夏令时自动处理，无任何网络请求。时间滑块基于本机当天日期推算各时区时刻；共同工作时段按两个时区各自的工作时间在 24 小时圆环上求交集，可自动处理跨天情况。": "Note: all times are computed locally with the browser's built-in Intl.DateTimeFormat and the IANA time zone database. Daylight saving time is handled automatically and no network requests are made. The time slider derives each zone's time from today's local date; overlapping work hours are computed on a 24-hour circle and handle day crossings automatically.",
 "世界时钟支持哪些时区？数据来自哪里？": "Which time zones does the world clock support, and where does the data come from?",
 "内置约50个常用城市与完整的IANA时区下拉列表，覆盖UTC-12到UTC+14。所有时间基于浏览器内置的Intl.DateTimeFormat与IANA时区数据库本地计算，不请求任何外部接口，时钟每秒刷新，也可拖动时间滑块查看一天内任意时刻。": "About 50 popular cities and the full IANA time zone dropdown are built in, covering UTC-12 to UTC+14. All times are computed locally with the browser's Intl.DateTimeFormat and the IANA time zone database, with no external requests. Clocks refresh every second, and the time slider lets you view any moment of the day.",
 "时间转换器如何把源时区的时间换算到目标时区？": "How does the time converter translate a source-zone time into target zones?",
 "先将源时区的墙上时间结合该时区当时的UTC偏移还原为准确的UTC时刻，再按目标时区的偏移格式化输出。换算过程自动处理夏令时，例如夏令时期间纽约与北京的时差会从13小时变为12小时，无需手动调整。": "The source wall time is first combined with that zone's UTC offset to reconstruct an exact UTC instant, then formatted for each target zone. Daylight saving time is handled automatically, so for example the New York to Beijing difference changes from 13 to 12 hours during DST, with no manual adjustment.",
 "工具如何判断一个时区是否实行夏令时？": "How does the tool tell whether a zone observes daylight saving time?",
 "通过对比该时区在当年1月与7月的UTC偏移：若两个月份偏移不同，说明该时区实行夏令时，时钟卡片会显示「夏令时」徽标；当当前偏移等于夏季偏移时，表示正处于夏令时期间。": "It compares the zone's UTC offset in January and July: if the two differ, the zone observes DST and the clock card shows a DST badge; when the current offset matches the summer offset, the zone is currently in daylight saving time.",
