 "PDF合并与拆分 - 在线PDF合并/拆分/旋转工具 | 在线工具大全": "PDF Merge & Split - Online PDF Merge / Split / Rotate Tool | Online Tools",
 "免费在线PDF合并与拆分工具，支持多文件按序合并、按页码范围拆分、每N页拆分、整篇页面旋转，100%浏览器本地处理，文件不上传，保护隐私安全。": "Free online PDF merge and split tool. Merge multiple files in order, split by page range, split every N pages, and rotate all pages. 100% browser-based local processing, files are never uploaded, keeping your data private.",
 "PDF合并与拆分 - 在线PDF合并/拆分/旋转工具": "PDF Merge & Split - Online PDF Merge / Split / Rotate Tool",
 "支持多文件按序合并、按页码范围拆分、每N页拆分、整篇页面旋转，全部在浏览器本地完成，文件不上传。": "Merge multiple files in order, split by page range, split every N pages, and rotate all pages - all done locally in your browser, with no file uploads.",
 "在线PDF合并、拆分与旋转工具，支持多文件按序合并、按页码范围拆分、每N页拆分为多份，并可对整篇页面统一旋转。所有操作均在浏览器本地完成，文件不会上传。": "Online PDF merge, split, and rotate tool. Merge multiple files in order, split by page range, split into multiple parts every N pages, and rotate all pages uniformly. All operations run locally in your browser and files are never uploaded.",
 "拆分": "Split",
