 "重新选择": "Choose Again",
 "100% 浏览器本地处理，文件不上传。": "100% browser-based local processing; files are never uploaded.",
 "合并时按文件列表顺序拼接，可为每个文件设置统一旋转角度；拆分支持按页码范围提取或按固定页数切片。加密、损坏或非 PDF 文件将被拒绝并提示。": "Merging concatenates files in list order, and you can set a uniform rotation angle for each file. Splitting supports extraction by page range or slicing by a fixed page count. Encrypted, corrupted, or non-PDF files will be rejected with a notice.",
 "PDF合并拆分工具会上传我的文件吗？": "Does the PDF merge and split tool upload my files?",
 "不会。所有读取、合并、拆分与旋转操作均在你的浏览器本地完成，文件不会上传到任何服务器，适合处理包含隐私或机密内容的文档。": "No. All reading, merging, splitting, and rotating operations run locally in your browser. Files are never uploaded to any server, so it is suitable for documents containing private or confidential content.",
 "合并后的PDF总页数是怎样的？": "What is the page count of a merged PDF?",
 "合并结果按文件列表的顺序依次拼接，总页数等于各文件页数之和。你可以在文件列表中调整上下顺序后再合并，也可以为某个文件的全部页面设置统一旋转角度。": "The merged result concatenates files in list order, and the total page count equals the sum of all files. You can reorder files in the list before merging, and you can also set a uniform rotation angle for all pages of a file.",
 "加密或损坏的PDF能处理吗？": "Can encrypted or corrupted PDFs be processed?",
 "加密（有打开密码）或严重损坏的PDF无法解析，工具会给出友好提示。请先解除密码保护或使用完整未损坏的文件后再进行操作。": "Encrypted (password-protected) or severely corrupted PDFs cannot be parsed, and the tool will show a friendly notice. Please remove password protection first, or use an intact, undamaged file before proceeding.",
 "免费在线PDF合并与拆分工具，支持多文件按序合并、按页码范围拆分、每N页拆分、整篇页面旋转，100%浏览器本地处理，文件不上传。": "Free online PDF merge and split tool. Merge multiple files in order, split by page range, split every N pages, and rotate all pages. 100% browser-based local processing; files are never uploaded.",
