 "免费在线二维码扫描器，支持上传图片、粘贴截图、摄像头实时扫描三种方式，自动识别并分类展示网址、WiFi、名片、电话、邮箱、地理位置等二维码内容，所有解析均在浏览器本地完成，图片与画面不会上传。": "Free online QR code scanner. It supports three modes: uploading an image, pasting a screenshot, and real-time camera scanning. QR content such as URLs, WiFi, vCards, phone numbers, emails, and locations is automatically recognized and displayed by category. All parsing runs locally in your browser; images and camera footage are never uploaded.",
 "二维码扫描器 - 本地图片/摄像头扫码识别工具": "QR Code Scanner - Local Image / Camera Scanning & Recognition Tool",
 "支持上传图片、粘贴截图、摄像头实时扫描三种方式，自动识别网址、WiFi、名片等二维码内容。": "Supports three modes - uploading an image, pasting a screenshot, and real-time camera scanning - with automatic recognition of QR content such as URLs, WiFi, and vCards.",
 "支持上传图片、粘贴截图、摄像头实时扫描三种方式，自动识别并分类展示网址、WiFi、名片、电话、邮箱、地理位置等二维码内容，全程本地处理。": "Supports three modes - uploading an image, pasting a screenshot, and real-time camera scanning - with automatic recognition and categorized display of QR content such as URLs, WiFi, vCards, phone numbers, emails, and locations. Everything is processed locally.",
