 "二维码扫描需要联网吗？": "Does QR code scanning require an internet connection?",
 "不需要。本工具 100% 在浏览器本地完成解码，图片和摄像头画面均不会上传到任何服务器，断网也可正常使用。": "No. This tool decodes 100% locally in your browser. Neither images nor camera footage are uploaded to any server, so it works even when you are offline.",
 "支持识别哪些二维码内容？": "What types of QR code content are supported?",
 "支持网址(URL)、WiFi、名片(vCard/MECARD)、电话、邮箱、短信、地理位置以及普通文本等多种格式，扫描后会自动分类并结构化展示。": "Supported formats include URLs, WiFi, vCards (vCard/MECARD), phone numbers, emails, SMS, locations, and plain text. After scanning, content is automatically categorized and displayed in a structured way.",
 "摄像头无法开启怎么办？": "What should I do if the camera cannot be started?",
 "摄像头需要在 HTTPS 安全上下文或 localhost 环境下才可用。若以 file:// 直接打开或访问非安全网络，浏览器会禁用摄像头，此时可使用上传图片或粘贴截图的方式扫码。": "The camera is only available in an HTTPS secure context or on localhost. If the page is opened via file:// or accessed over an insecure network, the browser will block camera access. In that case, use the upload image or paste screenshot mode instead.",
 "本地二维码扫描器，支持上传图片、粘贴截图、摄像头实时扫描，自动分类识别网址、WiFi、名片等格式。": "Local QR code scanner. Supports uploading an image, pasting a screenshot, and real-time camera scanning, with automatic categorization of formats such as URLs, WiFi, and vCards.",
