 "CSV转JSON - 在线CSV与JSON互相转换工具 | 在线工具大全": "CSV to JSON - Online CSV and JSON Converter | Online Tools",
 "免费在线CSV转JSON工具，支持逗号、分号、Tab、竖线等分隔符，RFC4180引号字段解析，首行表头识别，JSON数组转回CSV。全部处理在浏览器本地完成，支持复制与下载。": "Free online CSV to JSON tool supporting comma, semicolon, Tab and pipe delimiters, RFC4180 quoted field parsing, first-row header detection, and converting JSON arrays back to CSV. All processing is done locally in your browser, with copy and download support.",
 "CSV转JSON - 在线CSV与JSON互相转换工具": "CSV to JSON - Online CSV and JSON Converter",
 "支持多种分隔符与RFC4180引号解析的在线CSV/JSON互转工具，可复制与下载结果。": "Online CSV/JSON converter supporting multiple delimiters and RFC4180 quote parsing, with copy and download of results.",
 "在线 CSV 与 JSON 互相转换工具，支持多种分隔符与 RFC4180 引号字段解析，所有数据处理均在浏览器本地完成，不上传任何内容。": "Online CSV and JSON converter supporting multiple delimiters and RFC4180 quoted field parsing. All data processing is done locally in your browser and nothing is uploaded.",
