 "说明：解析支持 RFC4180 规范，被双引号包裹的字段内可包含分隔符、换行与双引号（连续两个双引号表示一个引号）。若字段含特殊字符，请务必使用引号包裹。": "Note: Parsing follows the RFC4180 standard. A field wrapped in double quotes may contain delimiters, line breaks and double quotes (two consecutive double quotes represent one quote). Always wrap fields containing special characters in quotes.",
 "输出分隔符": "Output Delimiter",
 "JSON 数组（对象数组或二维数组）": "JSON array (array of objects or 2D array)",
 "CSV 输出": "CSV Output",
 "下载 .csv": "Download .csv",
 "说明：对象数组会自动以首行键作为表头；二维数组则直接按行输出。含分隔符、引号或换行的字段会自动加引号转义。": "Note: An array of objects automatically uses the first-row keys as the header; a 2D array is output row by row. Fields containing delimiters, quotes or line breaks are automatically quoted and escaped.",
 "字段中含有逗号或换行怎么办？": "What if a field contains a comma or a line break?",
 "本工具遵循 RFC4180 规范，使用双引号包裹的字段可以包含分隔符、换行和双引号（双写表示一个引号）。未正确包裹会导致解析错位，建议始终为含特殊字符的字段加引号。": "This tool follows the RFC4180 standard: a field wrapped in double quotes may contain delimiters, line breaks and double quotes (doubling represents one quote). Improper wrapping will cause parsing misalignment, so always quote fields that contain special characters.",
 "首行作为表头是什么意思？": "What does Use first row as header mean?",
 "勾选后，CSV 第一行会被当作字段名称，输出为以表头为键的对象数组；不勾选则输出为二维数组（每个元素是一行的值数组），适合无表头的纯数据。": "When checked, the first CSV row is treated as the field names and the output is an array of objects keyed by the header; when unchecked, the output is a 2D array (each element is the array of values for one row), which suits header-less raw data.",
 "解析报错提示某行有问题怎么办？": "What should I do when parsing fails on a specific row?",
 "报错信息会指出具体行号，最常见的原因是引号未成对闭合。请检查该行是否遗漏了结束引号，或字段内引号是否按规范写成两个双引号。": "The error message points to the specific line number. The most common cause is an unpaired quote. Check whether a closing quote is missing on that line, or whether quotes inside a field are written as two double quotes as required.",
 "在线CSV与JSON互相转换工具，支持多种分隔符、RFC4180引号解析、首行表头识别。": "Online CSV and JSON converter supporting multiple delimiters, RFC4180 quote parsing and first-row header detection.",
