 "说明：粘贴对象数组后点击生成，浏览器会直接下载 .xlsx 文件，列名取自首行对象的键，缺失字段留空。": "Note: Paste an array of objects and click generate; the browser will download the .xlsx file directly. Column names come from the keys of the first object, and missing fields are left blank.",
 "支持哪些文件格式？": "Which file formats are supported?",
