 "HTTP状态码速查 - 完整HTTP状态码含义与处理建议 | 在线工具大全": "HTTP Status Codes - Complete Meanings and Handling Tips | Online Tools",
 "免费在线HTTP状态码速查表，收录1xx到5xx共60余种状态码，含英文标准名称、中文说明与常见原因处理建议。支持按状态码/名称模糊搜索与分类筛选，所有查询均在本地完成。": "Free online HTTP status code reference covering 60+ codes from 1xx to 5xx, with standard English names, descriptions and common causes with handling tips. Supports fuzzy search by code or name and category filtering; all lookups run locally.",
 "HTTP状态码速查 - 完整HTTP状态码含义与处理建议": "HTTP Status Codes - Complete Meanings and Handling Tips",
 "收录1xx到5xx共60余种HTTP状态码，含英文标准名称、中文说明与常见原因处理建议，支持搜索与分类筛选。": "Covers 60+ HTTP status codes from 1xx to 5xx, with standard English names, descriptions and common causes with handling tips, plus search and category filtering.",
 "收录 1xx 到 5xx 共 60 余种 HTTP 状态码，含英文标准名称、中文说明与常见原因/处理建议。支持按状态码、名称或说明模糊搜索与分类筛选，所有查询均在浏览器本地完成。": "Covers 60+ HTTP status codes from 1xx to 5xx, with standard English names, descriptions and common causes/handling tips. Supports fuzzy search by code, name or description and category filtering; all lookups run locally in your browser.",
 "搜索状态码 / 英文名称 / 中文说明，例如：404、redirect、重定向": "Search status code / English name / description, e.g. 404, redirect, redirect",
