 "301 和 302 重定向有什么区别？": "What is the difference between 301 and 302 redirects?",
 "301 Moved Permanently 表示资源已永久移动到新地址，浏览器和搜索引擎会更新书签与索引；302 Found 表示临时跳转，原地址仍在使用。二者都会自动重定向，但 301 对 SEO 的权重传递更明确。若需保持原请求方法（如 POST 仍是 POST），应使用 307（临时）或 308（永久）。": "301 Moved Permanently means the resource has moved to a new address permanently, and browsers and search engines will update bookmarks and indexes; 302 Found means a temporary jump and the original address is still in use. Both redirect automatically, but 301 passes SEO weight more explicitly. If you need to keep the original request method (e.g. POST stays POST), use 307 (temporary) or 308 (permanent).",
 "401 和 403 有什么不同？": "What is the difference between 401 and 403?",
 "401 Unauthorized 表示请求缺少有效的身份验证凭证，服务器要求先登录或携带 Token；403 Forbidden 表示已经过身份验证，但当前账号没有访问该资源的权限。简单说：401 是“你是谁”，403 是“你没权限”。": "401 Unauthorized means the request lacks valid authentication credentials and the server requires you to log in first or send a token; 403 Forbidden means you are authenticated but the current account has no permission to access the resource. In short: 401 asks who you are, while 403 says you do not have permission.",
 "出现 5xx 错误应该如何处理？": "How should I handle 5xx errors?",
 "5xx 表示服务器侧出错。常见如 500（代码异常，查服务端日志）、502/504（网关/代理上游无响应或超时，检查后端是否存活或过载）、503（服务暂时不可用，常在维护或限流，可参考 Retry-After 头稍后重试）。多数 5xx 需要服务端排查，客户端可先重试确认是否为偶发。": "5xx indicates a server-side error. Common cases: 500 (code exception, check the server logs), 502/504 (no response from or timeout on the gateway/proxy upstream; check whether the backend is alive or overloaded), 503 (service temporarily unavailable, often during maintenance or rate limiting; retry later per the Retry-After header). Most 5xx errors require server-side troubleshooting; clients can retry first to confirm whether it is intermittent.",
 "在线HTTP状态码速查工具，收录1xx到5xx共60余种状态码，含英文标准名称、中文说明与常见原因处理建议，支持搜索与分类筛选。": "Online HTTP status code reference covering 60+ codes from 1xx to 5xx, with standard English names, descriptions and common causes with handling tips, plus search and category filtering.",
 "按状态码搜索": "Search by status code",
 "按名称/说明模糊匹配": "Fuzzy match by name/description",
