 "在上方输入合法 JSON 后，这里会展示树形结构": "Enter valid JSON above and the tree structure will be shown here",
 "JSON 校验报错会给出位置吗？": "Does JSON validation report the error position?",
 "会。当 JSON 语法有误时，工具会解析错误信息并换算出具体的「第几行第几列」，帮助你快速定位问题所在。": "Yes. When the JSON syntax is invalid, the tool parses the error message and works out the exact line and column, helping you locate the problem quickly.",
 "路径查询支持什么格式？": "What path format does path query support?",
 "支持形如 $.store.book[0].title 的路径写法：对象属性用点号，数组元素用方括号索引。输入路径后点击定位即可高亮对应节点。": "It supports path syntax like $.store.book[0].title: object properties use dots and array elements use bracket indexes. Enter a path and click Locate to highlight the matching node.",
 "可以直接复制某个节点的值或路径吗？": "Can I copy the value or path of a node directly?",
 "可以。将鼠标悬停在任意节点行上，会出现「复制值」和「复制路径」两个按钮，分别复制该节点的 JSON 值与完整路径字符串。": "Yes. Hover over any node row and two buttons appear, Copy Value and Copy Path, which copy the node JSON value and the full path string respectively.",
 "在线JSON校验、树形视图与路径查询工具，支持节点着色与复制。": "Online JSON validation, tree view and path query tool with node coloring and copying.",
 "JSON 语法校验（含行列号）": "JSON syntax validation (with line/column numbers)",
