 "房贷计算器 - 商业贷款/公积金组合贷月供计算（等额本息/等额本金） | 在线工具大全": "Mortgage Calculator - Commercial/Provident Fund Loan Monthly Payment (Equal Installment / Equal Principal) | Online Tools",
 "免费在线房贷计算器，支持商业贷款与公积金组合贷款，可选等额本息或等额本金还款方式，一键计算月供、总利息、总还款额，并生成完整还款计划表，数据本地计算不上传。": "Free online mortgage calculator supporting commercial loans and combined commercial/provident fund loans, with equal installment or equal principal repayment. Calculate the monthly payment, total interest and total repayment in one click, and generate a full repayment schedule. All calculations run locally and no data is uploaded.",
 "房贷计算器 - 月供/利息/还款计划一键计算": "Mortgage Calculator - Monthly Payment, Interest and Schedule in One Click",
 "支持商业贷款、公积金组合贷款，等额本息与等额本金两种方式，一键计算月供、总利息与完整还款计划。": "Supports commercial loans, combined provident fund loans, and both equal installment and equal principal methods, calculating the monthly payment, total interest and full repayment schedule in one click.",
 "支持商业贷款与公积金组合贷款，可选等额本息或等额本金还款方式，实时计算月供、总利息、总还款额，并生成完整还款计划表。所有数据本地计算，不上传服务器。": "Supports commercial loans and combined commercial/provident fund loans, with equal installment or equal principal repayment. Instantly calculate the monthly payment, total interest and total repayment, and generate a full repayment schedule. All data is computed locally and never uploaded to a server.",
