 "请输入有效的贷款信息": "Please enter valid loan information",
 "说明：等额本息月供 = 本金 × 月利率 × (1+月利率)^期数 ÷ [(1+月利率)^期数 − 1]；等额本金每月归还固定本金，月供 = 本金÷期数 + 剩余本金 × 月利率。组合贷款中商业与公积金部分分别计算后相加。利率如有变动以银行最新公布为准，本工具结果仅供预算参考。": "Note: For equal installment, the monthly payment = principal x monthly rate x (1+monthly rate)^periods / [(1+monthly rate)^periods - 1]; for equal principal, a fixed amount of principal is repaid each month and the monthly payment = principal/periods + remaining principal x monthly rate. For a combined loan, the commercial and provident fund portions are calculated separately and then added together. If rates change, the latest figures published by the bank prevail; results from this tool are for budgeting reference only.",
 "等额本息和等额本金有什么区别？": "What is the difference between equal installment and equal principal?",
 "等额本息每月还款额固定，前期利息占比高、本金占比低；等额本金每月归还固定本金，月供逐月递减，总利息更少，但前期还款压力较大。以100万元贷款30年、年利率3.1%估算，等额本息总利息约53.7万元，等额本金约46.6万元。": "With equal installment, the monthly repayment is fixed and interest makes up a larger share early on while principal is smaller; with equal principal, a fixed amount of principal is repaid each month, the monthly payment decreases month by month, and total interest is lower, but early repayment pressure is greater. For example, for a 1 million loan over 30 years at 3.1% annual interest, total interest is about 537,000 with equal installment versus about 466,000 with equal principal.",
 "组合贷款是怎么计算的？": "How is a combined loan calculated?",
 "组合贷款即商业贷款与公积金贷款两部分，分别按各自的本金、利率和相同年限计算月供后相加。本工具支持两部分独立设置金额与利率。": "A combined loan consists of a commercial loan and a provident fund loan. Each part is calculated with its own principal, rate and the same term, and the monthly payments are then added together. This tool lets you set the amount and rate for each part independently.",
 "计算结果准确吗？": "Are the calculation results accurate?",
 "计算基于标准金融公式在浏览器本地完成，与银行等额本息/等额本金算法一致。实际还款以银行合同为准（利率变动、还款日、宽限期等因素银行会有细微差异），结果仅供预算参考。": "The calculations use standard financial formulas and run locally in your browser, matching the bank algorithms for equal installment/equal principal. Actual repayment follows the bank contract (rates, repayment dates and grace periods may differ slightly), so results are for budgeting reference only.",
 "在线房贷计算器，支持商业贷款与公积金组合贷款，等额本息与等额本金两种还款方式，可计算月供、总利息并生成还款计划表。": "Online mortgage calculator supporting commercial loans and combined provident fund loans, with equal installment and equal principal repayment, calculating the monthly payment and total interest and generating a repayment schedule.",
