 "Query参数解析 - URL查询字符串解析与重组 | 在线工具大全": "Query Parameter Parser - URL Query String Parsing and Rebuilding | Online Tools",
 "免费在线Query参数解析工具，输入完整URL或query string即可解析出参数键值表，支持编辑、增删、编码开关与实时重组URL，一键复制。所有解析在浏览器本地完成，不上传数据。": "Free online query parameter parser. Enter a full URL or query string to parse it into a key-value parameter table, with support for editing, adding and removing parameters, an encoding toggle and real-time URL rebuilding, all with one-click copying. All parsing is done locally in your browser and no data is uploaded.",
 "Query参数解析 - URL查询字符串解析与重组": "Query Parameter Parser - URL Query String Parsing and Rebuilding",
 "输入完整URL或query string即可解析出参数键值表，支持编辑、增删、编码开关与实时重组URL，一键复制。": "Enter a full URL or query string to parse it into a key-value parameter table, with support for editing, adding and removing parameters, an encoding toggle and real-time URL rebuilding, all with one-click copying.",
 "输入完整 URL 或 query string（?a=1&b=2），自动解析为参数键值表格，支持编辑、增删、编码开关与实时重组 URL。所有解析均在浏览器本地完成，不上传任何数据。": "Enter a full URL or query string (?a=1&b=2) to automatically parse it into a key-value parameter table, with support for editing, adding and removing parameters, an encoding toggle and real-time URL rebuilding. All parsing is done locally in your browser and no data is uploaded.",
 "输入 URL 或 query string": "Enter a URL or query string",
 "例如：https://example.com/search?q=关键词&page=2#result 或 ?a=1&b=2 或 a=1&b=2": "e.g. https://example.com/search?q=keyword&page=2#result, ?a=1&b=2, or a=1&b=2",
