 "复制URL": "Copy URL",
 "工具支持解析哪些格式的输入？": "What input formats does the tool support?",
 "支持完整 URL（会自动提取问号后的 query 部分）、带问号的 query string（如 ?a=1&b=2）以及不带问号的纯参数串（如 a=1&b=2）。URL 中的 #hash 片段会被单独保留，不会被当作参数。": "It supports full URLs (the query part after the question mark is extracted automatically), query strings with a question mark (e.g. ?a=1&b=2), and bare parameter strings without one (e.g. a=1&b=2). A #hash fragment in the URL is preserved separately and is not treated as a parameter.",
 "编码开关起什么作用？": "What does the encoding toggle do?",
 "开启后，重组 URL 时每个参数值都会经过 encodeURIComponent 编码，适合直接用于请求；关闭后则原样拼接，适合查看或构造带中文/特殊字符的可读链接。参数表中也会标注每一行当前是否为 URL 编码状态。": "When on, every parameter value is encoded with encodeURIComponent while rebuilding the URL, which is suitable for direct use in requests; when off, values are concatenated as-is, which is suitable for viewing or building readable links with Chinese/special characters. The parameter table also marks whether each row is currently URL-encoded.",
 "粘贴进去的 URL 含 #hash 会怎样？": "What happens if the pasted URL contains a #hash?",
 "工具会正确地把 # 之后的部分识别为 hash（片段标识符）并单独保留，不会混入参数。重组后的 URL 也会把 hash 原样拼接在末尾。": "The tool correctly recognizes the part after # as the hash (fragment identifier) and preserves it separately, without mixing it into the parameters. The rebuilt URL also appends the hash unchanged at the end.",
 "在线Query参数解析工具，解析完整URL或query string为参数键值表，支持编辑、增删、编码开关与实时重组URL。": "Online query parameter parser that turns full URLs or query strings into a key-value parameter table, with support for editing, adding and removing parameters, an encoding toggle and real-time URL rebuilding.",
