 "免费在线SQL转义工具，支持单引号加倍、反斜杠与换行回车制表符NUL转义、转义还原，以及多行文本一键生成 'a','b','c' 形式的 IN 列表，全部浏览器本地处理。": "Free online SQL escape tool supporting single-quote doubling, backslash, line break, carriage return, tab and NUL escaping, unescaping, and one-click generation of 'a','b','c' style IN lists from multi-line text, all processed locally in your browser.",
 "SQL转义 - 在线SQL字符串转义与IN列表生成": "SQL Escape - Online SQL String Escaping and IN List Generation",
 "支持单引号加倍、控制字符转义与IN列表生成的一站式SQL转义工具，全程本地处理。": "An all-in-one SQL escape tool with single-quote doubling, control character escaping and IN list generation, processed entirely locally.",
 "在线 SQL 字符串转义与 IN 列表生成工具，支持单引号加倍、反斜杠与控制字符转义、转义还原，以及多行文本一键生成 IN 列表。": "Online SQL string escaping and IN list generation tool supporting single-quote doubling, backslash and control character escaping, unescaping, and one-click IN list generation from multi-line text.",
