 "条件。": " conditions.",
 "为什么要对 SQL 字符串做转义？": "Why escape SQL strings?",
 "字符串中的单引号会破坏 SQL 语句结构，甚至引发 SQL 注入。将单引号写成两个单引号（''）是最基础的转义方式，可确保字符串被数据库正确解析。": "A single quote inside a string can break the SQL statement structure and even lead to SQL injection. Writing single quotes as two single quotes ('') is the most basic escaping method and ensures the string is parsed correctly by the database.",
 "换行、制表符等控制字符如何转义？": "How are control characters such as line breaks and tabs escaped?",
 "工具会把实际的换行、回车、制表符与 NUL 字符分别转义为 \\n、\\r、\\t、\\0 形式的文本，并把反斜杠本身转义为 \\\\，便于安全地写入 SQL 语句。": "The tool escapes actual line breaks, carriage returns, tabs and NUL characters into the text forms \\n, \\r, \\t and \\0 respectively, and escapes the backslash itself as \\\\, so the result can be written safely into SQL statements.",
 "IN 列表生成有什么用？": "What is IN list generation for?",
 "把每行一个的取值自动整理成 'a','b','c' 的逗号分隔形式，可直接粘贴进 IN (...) 条件，自动去除空行并加引号。": "It automatically turns one value per line into a comma-separated form like 'a','b','c' that can be pasted directly into an IN (...) condition, removing blank lines and adding quotes automatically.",
 "在线SQL字符串转义与IN列表生成工具，支持单引号加倍、控制字符转义与还原。": "Online SQL string escaping and IN list generation tool with single-quote doubling, control character escaping and unescaping.",
