 "SQL格式化 - 在线SQL美化与压缩工具 | 在线工具大全": "SQL Formatter - Online SQL Beautifier and Minifier | Online Tools",
 "免费在线SQL格式化工具，支持关键字大写、主子句换行、AND/OR 缩进、逗号换行、2/4 空格缩进与单行压缩，保留字符串与注释内容，全部在浏览器本地处理。": "Free online SQL formatter supporting keyword uppercasing, main clause line breaks, AND/OR indentation, comma line breaks, 2/4 space indentation and single-line minification, while preserving strings and comments. Everything is processed locally in your browser.",
 "SQL格式化 - 在线SQL美化与压缩工具": "SQL Formatter - Online SQL Beautifier and Minifier",
 "支持关键字大写、子句换行、AND/OR 缩进与单行压缩的在线SQL格式化工具，保留字符串与注释。": "Online SQL formatter with keyword uppercasing, clause line breaks, AND/OR indentation and single-line minification, preserving strings and comments.",
 "在线 SQL 美化与压缩工具，支持关键字大写、主子句换行、AND/OR 缩进、逗号换行与自定义缩进，字符串与注释原样保留，全程浏览器本地处理。": "Online SQL beautifier and minifier supporting keyword uppercasing, main clause line breaks, AND/OR indentation, comma line breaks and custom indentation, with strings and comments preserved unchanged. Everything is processed locally in your browser.",
