 "格式化结果会显示在这里": "The formatted result will appear here",
 "说明：工具会识别常见 SQL 关键字并统一大写，主子句（SELECT/FROM/WHERE/JOIN 等）换行，AND/OR 缩进显示；单引号字符串、双引号标识符与注释内容均原样保留。": "Note: the tool recognizes common SQL keywords and uppercases them uniformly, breaks main clauses (SELECT/FROM/WHERE/JOIN, etc.) onto new lines and indents AND/OR; single-quoted strings, double-quoted identifiers and comments are preserved unchanged.",
 "SQL 关键字会自动大写吗？": "Are SQL keywords uppercased automatically?",
 "是的，工具会识别常见的 SQL 关键字（如 SELECT、FROM、WHERE、JOIN 等）并统一转为大写，而表名、列名等标识符会保持原有大小写不变。": "Yes. The tool recognizes common SQL keywords (such as SELECT, FROM, WHERE and JOIN) and uppercases them uniformly, while identifiers such as table and column names keep their original casing.",
 "字符串和注释会被修改吗？": "Are strings and comments modified?",
 "不会。单引号字符串、双引号标识符以及 -- 和 /* */ 注释内容都会被原样保留，不会被格式化或破坏。": "No. Single-quoted strings, double-quoted identifiers and -- and /* */ comments are all preserved unchanged; they are neither reformatted nor broken.",
 "压缩模式有什么用？": "What is the minify mode for?",
 "压缩模式会把 SQL 折叠为单行并去除多余空白，常用于日志、配置或传输场景，便于复制与比对，关键字同样会大写。": "Minify mode collapses SQL into a single line and removes extra whitespace. It is commonly used for logs, configuration or transmission, making copying and comparison easier, and keywords are uppercased as well.",
 "在线SQL美化与压缩工具，支持关键字大写、子句换行、AND/OR 缩进、逗号换行与单行压缩。": "Online SQL beautifier and minifier with keyword uppercasing, clause line breaks, AND/OR indentation, comma line breaks and single-line minification.",
