 "User-Agent解析 - 浏览器/系统/设备/爬虫识别 | 在线工具大全": "User-Agent Parser - Browser/OS/Device/Bot Detection | Online Tools",
 "免费在线User-Agent解析工具，粘贴或自动识别UA字符串，解析浏览器名称与版本、渲染引擎、操作系统、设备类型及是否为爬虫机器人。支持一键填入常用UA示例，所有解析在本地正则完成。": "Free online User-Agent parser. Paste or auto-detect a UA string to parse the browser name and version, rendering engine, operating system, device type and whether it is a crawler bot. Supports one-click insertion of common UA examples; all parsing is done with local regular expressions.",
 "User-Agent解析 - 浏览器/系统/设备/爬虫识别": "User-Agent Parser - Browser/OS/Device/Bot Detection",
 "粘贴或自动识别UA字符串，解析浏览器、渲染引擎、操作系统、设备类型及是否爬虫机器人，支持常用UA示例一键填入。": "Paste or auto-detect a UA string to parse the browser, rendering engine, operating system, device type and whether it is a crawler bot, with one-click insertion of common UA examples.",
 "粘贴或自动识别 User-Agent 字符串，本地解析浏览器名称与版本、渲染引擎、操作系统与版本、设备类型以及是否为爬虫机器人。打开页面会自动填入当前浏览器 UA，所有解析在浏览器本地正则完成，不上传数据。": "Paste or auto-detect a User-Agent string to parse locally the browser name and version, rendering engine, operating system and version, device type and whether it is a crawler bot. Opening the page auto-fills the current browser UA; all parsing is done with local regular expressions in your browser and no data is uploaded.",
 "User-Agent 字符串": "User-Agent String",
 "粘贴 UA 字符串，页面加载时会自动填入当前浏览器 UA": "Paste a UA string; the current browser UA is auto-filled when the page loads",
