 "解析结果 JSON（可复制）": "Parsed Result JSON (copyable)",
 "解析结果将生成为 JSON 显示在此": "The parsed result will be generated and shown here as JSON",
 "User-Agent 能准确识别所有浏览器吗？": "Can User-Agent strings identify every browser accurately?",
 "UA 字符串由浏览器自行声明，理论上可被伪造，因此解析结果是基于字符串模式的“尽力识别”。常见浏览器（Chrome、Firefox、Safari、Edge、微信/QQ内置浏览器等）识别可靠；对小众或高度定制的浏览器，可能只能识别到内核层级。本工具所有匹配均为本地正则，不上传任何信息。": "UA strings are declared by the browser itself and can theoretically be forged, so parsing is a best-effort identification based on string patterns. Common browsers (Chrome, Firefox, Safari, Edge, WeChat/QQ built-in browsers, etc.) are identified reliably; for niche or heavily customized browsers, only the engine level may be recognized. All matching in this tool uses local regular expressions and no information is uploaded.",
 "如何判断访问者是不是爬虫或机器人？": "How can I tell whether a visitor is a crawler or bot?",
 "工具会检测 UA 中是否含 Googlebot、Baiduspider、Bingbot、Yandex、字节/神马等典型爬虫标识，或通用 Spider/Crawler/Bot 关键字。命中则标记为爬虫机器人，便于做统计或反爬分析。": "The tool checks whether the UA contains typical crawler identifiers such as Googlebot, Baiduspider, Bingbot, Yandex, Bytespider or Shenma, or the generic keywords Spider/Crawler/Bot. If matched, it is flagged as a crawler bot, which helps with statistics or anti-bot analysis.",
 "为什么同一台电脑不同浏览器内核写法不同？": "Why do different browsers on the same computer write the engine differently?",
 "现代浏览器多基于 Chromium（Blink 引擎），但 UA 中会保留历史兼容字段（如 Safari 的版本、AppleWebKit 标识）。工具会综合各字段，优先以真实产品名（如 Edge、Chrome）覆盖内核名，给出更贴近实际的产品判断。": "Modern browsers are mostly based on Chromium (the Blink engine), but the UA retains legacy compatibility fields (such as the Safari version and AppleWebKit identifier). The tool synthesizes these fields and prefers the real product name (such as Edge or Chrome) over the engine name, giving a product judgment closer to reality.",
 "在线User-Agent解析工具，解析浏览器名称与版本、渲染引擎、操作系统、设备类型及是否为爬虫机器人，支持常用UA示例一键填入。": "Online User-Agent parser that parses the browser name and version, rendering engine, operating system, device type and whether it is a crawler bot, with one-click insertion of common UA examples.",
