 "Base64编解码 - 在线文本/图片Base64转换工具 | 在线工具大全": "Base64 Encoder/Decoder - Online Text/Image Base64 Converter | Online Tools",
 "免费在线Base64编解码工具，支持 UTF-8 安全的文本编码与解码、URL 安全模式（+/ 与 -_ 互换），以及图片转 Base64 DataURL（支持拖入、含/不含 MIME、转 CSS 与 HTML img），本地处理不上传。": "Free online Base64 encoder/decoder with UTF-8 safe text encoding and decoding, URL-safe mode (+/ and -_ swapped), and image to Base64 DataURL conversion (with drag and drop, optional MIME prefix, and CSS and HTML img output). All processing is done locally and nothing is uploaded.",
