 "在线 Base64 编解码工具，UTF-8 安全的文本编码解码（含 URL 安全模式），支持图片一键转为 Base64 DataURL 并可反向还原为图片预览与下载，全程浏览器本地处理。": "Online Base64 encoder/decoder with UTF-8 safe text encoding and decoding (including URL-safe mode), one-click image to Base64 DataURL conversion, and reverse restoration to image preview and download, all processed locally in the browser.",
