 "Base64 编码后是加密吗？": "Is Base64 a form of encryption?",
 "不是。Base64 只是一种编码方式，用于把二进制或文本数据表示成可打印字符，可被任何人或程序轻松还原，不具备保密性。它常用于在只支持文本的场合传输二进制数据（如邮件、DataURL）。": "No. Base64 is only an encoding scheme that represents binary or text data as printable characters. It can be easily restored by anyone or any program and provides no confidentiality. It is commonly used to transmit binary data in text-only contexts such as email or DataURLs.",
 "为什么中文 / Emoji 编解码会乱码？": "Why do Chinese or Emoji characters get garbled when encoding or decoding?",
 "原生 btoa 只支持 Latin1 字符。本工具先用 TextEncoder 把文本按 UTF-8 编码成字节再转 Base64，因此中文、Emoji 等都能正确处理，不会出现乱码。": "The native btoa function only supports Latin1 characters. This tool first uses TextEncoder to encode text into UTF-8 bytes before converting to Base64, so Chinese, Emoji and other characters are handled correctly without garbled output.",
 "URL 安全模式有什么用？": "What is URL-safe mode used for?",
 "标准 Base64 含 + 和 /，在 URL 或文件名中会被转义。URL 安全模式把 + 替换为 -、/ 替换为 _，并去掉填充等号，适合把编码结果直接放进链接或参数中。": "Standard Base64 contains + and /, which get escaped in URLs and file names. URL-safe mode replaces + with - and / with _ and drops the padding equals signs, making it suitable for putting encoded results directly into links or parameters.",
 "在线Base64编解码工具，支持 UTF-8 安全的文本编码解码与图片转 Base64 DataURL。": "Online Base64 encoder/decoder with UTF-8 safe text encoding and decoding and image to Base64 DataURL conversion.",
