 "JSON格式化 - 在线JSON美化/压缩/校验工具 | 在线工具大全": "JSON Formatter - Online JSON Beautifier / Minifier / Validator | Online Tools",
 "免费在线JSON格式化工具，支持JSON美化（2空格/4空格/Tab缩进）、压缩成单行、转义与去转义、语法校验并精确定位错误行列，提供可折叠树形视图，本地处理不上传，适合接口调试与数据查看。": "Free online JSON formatter with JSON beautification (2-space / 4-space / Tab indentation), minification to a single line, escaping and unescaping, and syntax validation with precise error line and column location. It also provides a collapsible tree view. All processing is done locally and nothing is uploaded, making it ideal for API debugging and data inspection.",
