 "支持JSON美化、压缩、转义、去转义与语法校验的在线工具，可折叠树形视图，本地处理不上传。": "Online tool for JSON beautification, minification, escaping, unescaping and syntax validation, with a collapsible tree view. All processing is done locally and nothing is uploaded.",
