 "JSON校验提示错误时如何定位问题？": "How do I locate the problem when JSON validation reports an error?",
 "本工具在解析失败时会给出错误原因以及出错位置的行号与列号，并标注字符偏移量。常见原因包括：多余的逗号、缺少引号、键名未用双引号、结尾多出的括号等。根据行列号回到原文修改即可。": "When parsing fails, this tool shows the error reason along with the line and column numbers of the error position, and marks the character offset. Common causes include extra commas, missing quotes, keys not wrapped in double quotes, and extra brackets at the end. Go back to the original text and fix it based on the line and column numbers.",
 "JSON格式化会改变数据内容吗？": "Does JSON formatting change the data content?",
 "不会。美化/压缩/转义/去转义都只是改变文本的表现形式（缩进、空白、引号转义），不会改变数据的结构与值。校验通过后再格式化是安全的。": "No. Beautifying, minifying, escaping and unescaping only change how the text is presented (indentation, whitespace, quote escaping); they do not change the structure or values of the data. It is safe to format after validation passes.",
 "大体积的JSON粘贴进来会卡吗？": "Will pasting a large JSON document cause lag?",
 "内容超过 1MB 时工具会提示性能风险，建议关闭实时格式化、先校验结构，或拆分后再处理。所有解析均在浏览器本地完成，不会上传到服务器。": "When the content exceeds 1MB, the tool warns about the performance risk. It is recommended to turn off real-time formatting, validate the structure first, or split the content before processing. All parsing is done locally in the browser and is never uploaded to a server.",
 "在线JSON格式化工具，支持美化、压缩、转义、去转义与语法校验，并提供可折叠树形视图。": "Online JSON formatter supporting beautification, minification, escaping, unescaping and syntax validation, plus a collapsible tree view.",
