 "JWT解析 - 在线JWT解码/Token解析工具 | 在线工具大全": "JWT Decoder - Online JWT Decoding / Token Parser | Online Tools",
 "免费在线JWT解析工具，实时解码三段式（Header.Payload.Signature）JSON Web Token，安全处理 base64url，高亮 iss/sub/aud/exp/iat/nbf/jti 标准字段并换算人类可读时间，所有解析在浏览器本地完成。": "Free online JWT decoder: decode three-part (Header.Payload.Signature) JSON Web Tokens in real time, safely handle base64url, highlight standard claims such as iss, sub, aud, exp, iat, nbf and jti, and convert them into human-readable times. All parsing is done locally in the browser.",
 "JWT解析 - 在线JWT解码/Token解析工具": "JWT Decoder - Online JWT Decoding / Token Parser",
 "实时解码三段式 JSON Web Token，高亮标准字段并换算人类可读时间，本地解析不上传。": "Decode three-part JSON Web Tokens in real time, highlight standard claims and convert them into human-readable times. Parsing is local and nothing is uploaded.",
 "在线 JSON Web Token 解析工具，实时解码三段式 Token（Header / Payload / Signature），安全处理 base64url，高亮标准字段并换算人类可读时间，所有解析在浏览器本地完成，不上传服务器。": "Online JSON Web Token parser: decode three-part tokens (Header / Payload / Signature) in real time, safely handle base64url, highlight standard claims and convert them into human-readable times. All parsing is done locally in the browser and nothing is uploaded to a server.",
 "JWT（粘贴完整的三段式 Token）": "JWT (paste the complete three-part token)",
 "JSON 美化": "Pretty JSON",
 "Header（头部）解码结果": "Header (decoded)",
 "Payload（载荷）解码结果": "Payload (decoded)",
 "原文（不可读）": "Raw (not decoded)",
 "Signature（签名）原文": "Signature (raw)",
 "标准字段（Standard Claims）": "Standard Claims",
 "安全提示：": "Security note: ",
 "JWT 的前两段（Header、Payload）只是经过 base64url 编码，": "The first two parts of a JWT (Header and Payload) are only base64url-encoded, ",
 "并非加密": "not encrypted",
 "，任何人都能解码查看内容；真正的防伪在第三段的 Signature。请勿在不可信站点粘贴含有敏感身份或权限信息的 Token。本工具仅做本地解析，不上传任何数据。": ", so anyone can decode and view the contents. Real tamper protection comes from the third part, the Signature. Do not paste tokens containing sensitive identity or permission information on untrusted sites. This tool only parses data locally and never uploads anything.",
 "JWT 由哪几部分组成？": "What parts make up a JWT?",
 "JWT（JSON Web Token）由三段用英文点号「.」连接而成：第一段是 Header（头部，声明算法与类型），第二段是 Payload（载荷，存放业务与标准声明），第三段是 Signature（签名，由前两段用密钥签名得到）。解码前两段可查看内容，但签名需在服务端用密钥校验。": "A JWT (JSON Web Token) consists of three parts joined by dots: the first part is the Header (which declares the algorithm and type), the second is the Payload (which carries business and standard claims), and the third is the Signature (produced by signing the first two parts with a secret key). Decoding the first two parts lets you view the content, but the signature must be verified on the server with the secret key.",
 "exp / iat / nbf 这些时间字段是什么？": "What are the time fields exp, iat and nbf?",
 "它们都是 Unix 秒级时间戳：exp 表示过期时间、iat 表示签发时间、nbf 表示在此时间之前不可用（Not Before）。本工具会将其换算成可读时间，并对 exp、iat、nbf 显示是否已过期 / 是否生效的徽标。": "They are all Unix timestamps in seconds: exp is the expiration time, iat is the issued-at time, and nbf means the token is not usable before this time (Not Before). This tool converts them into readable times and shows badges for exp, iat and nbf indicating whether the token has expired or taken effect.",
 "在网页里粘贴 JWT 安全吗？": "Is it safe to paste a JWT into a web page?",
 "本工具所有解析都在浏览器本地完成，不会把 Token 上传到任何服务器。但仍建议在不可信的第三方站点谨慎粘贴包含敏感信息（如身份、权限）的 Token。请仅在可信的本地工具中解析。": "All parsing in this tool is done locally in the browser and no token is ever uploaded to any server. However, you should still be careful about pasting tokens that contain sensitive information (such as identity or permissions) on untrusted third-party sites. Only parse tokens in trusted local tools.",
 "在线JWT解析工具，实时解码三段式 JSON Web Token 并高亮标准字段。": "Online JWT decoder that decodes three-part JSON Web Tokens in real time and highlights standard claims.",
