 "正则表达式在线测试 - 实时匹配验证与替换工具 | 在线工具大全": "Online Regex Tester - Live Match Validation and Replacement Tool | Online Tools",
 "免费在线正则表达式测试工具，实时高亮匹配结果，支持分组捕获查看、替换测试（$1/$&语法）、常用正则速查（邮箱/手机号/URL/IP等），输入即测，本地运行不上传。": "Free online regular expression tester with live highlighting of matches, capture group viewing, replacement testing ($1/$& syntax) and a cheat sheet of common regexes (email, phone number, URL, IP and more). Type to test instantly; everything runs locally and nothing is uploaded.",
 "正则表达式在线测试 - 实时匹配验证与替换工具": "Online Regex Tester - Live Match Validation and Replacement Tool",
 "在线正则表达式测试工具，实时高亮匹配结果，支持分组捕获、替换测试与常用正则速查，本地运行不上传。": "Online regular expression tester with live highlighting of matches, capture group support, replacement testing and a cheat sheet of common regexes. Everything runs locally and nothing is uploaded.",
