 "不会。所有匹配计算均在您的浏览器本地通过JavaScript RegExp完成，正则和测试文本都不会离开您的设备。": "No. All matching is performed locally in your browser with the JavaScript RegExp engine, and neither the regular expression nor the test text ever leaves your device.",
 "修饰符 g、i、m、s 分别表示什么？": "What do the flags g, i, m and s mean?",
 "g表示全局匹配（查找所有匹配而非仅第一个）；i表示忽略大小写；m表示多行模式（^和$匹配每行开头结尾）；s表示点号匹配换行符；u表示Unicode模式；y表示粘性匹配（从lastIndex处开始）。": "g means global matching (find all matches instead of only the first); i means ignore case; m means multiline mode (^ and $ match the start and end of each line); s means the dot matches newline characters; u means Unicode mode; y means sticky matching (matching starts from lastIndex).",
 "替换中的 $1、$&amp; 是什么意思？": "What do $1 and $&amp; mean in replacements?",
 "$1到$9表示引用第1到第9个捕获分组的内容；$&amp;表示整个匹配文本；$`表示匹配文本之前的内容；$'表示匹配文本之后的内容；$$表示字面量美元符号。": "$1 to $9 refer to the contents of capture groups 1 through 9; $&amp; means the entire matched text; $` means the content before the matched text; $' means the content after the matched text; $$ means a literal dollar sign.",
 "在线正则表达式测试工具，实时高亮匹配结果，支持分组捕获查看、替换测试与常用正则速查。": "Online regular expression tester with live highlighting of matches, capture group viewing, replacement testing and a cheat sheet of common regexes.",
