 "HTML格式化 - 在线HTML美化压缩与标签检测工具 | 在线工具大全": "HTML Formatter - Online HTML Beautify, Minify & Tag Checker | Online Tools",
 "免费在线HTML格式化工具，支持按层级缩进美化（2空格/4空格/Tab，属性可换行对齐）、压缩去注释去多余空白、HTML实体转义与反转义，并能检测未闭合标签，纯本地处理。": "Free online HTML formatter that supports indented beautification by level (2 spaces / 4 spaces / Tab, with optional attribute line breaks and alignment), minification with comment and extra whitespace removal, HTML entity escape and unescape, and unclosed tag detection. All processing is done locally.",
 "HTML格式化 - 在线HTML美化压缩与标签检测工具": "HTML Formatter - Online HTML Beautify, Minify & Tag Checker",
 "在线HTML格式化工具，支持美化、压缩、转义反转义与标签未闭合检测，本地处理不上传。": "Online HTML formatter with beautify, minify, escape / unescape and unclosed tag detection. Processed locally, nothing uploaded.",
 "操作模式": "Operation Mode",
 "粘贴需要格式化/压缩/转义的 HTML 代码": "Paste HTML code to format, minify or escape",
 "处理结果会显示在这里": "The result will appear here",
 "在线HTML格式化工具，支持美化、压缩、转义反转义与标签未闭合检测。": "Online HTML formatter with beautify, minify, escape / unescape and unclosed tag detection.",
 "层级缩进美化": "Indented Beautify",
