 "压缩去注释空白": "Minify (remove comments & whitespace)",
 "HTML实体转义/反转义": "HTML Entity Escape / Unescape",
 "未闭合标签检测": "Unclosed Tag Detection",
 "本地处理不上传": "Processed Locally, Nothing Uploaded",
 "压缩会破坏 <pre>、<textarea>、<script> 里的内容吗？": "Will minification break the content inside <pre>, <textarea> and <script>?",
 "不会。压缩功能会完整保留 <pre>、<textarea>、<script> 标签内的原始内容（包括其中的空格与换行），只去除标签之间的多余空白与注释，因此代码块与脚本不会被误改。": "No. Minification fully preserves the original content inside <pre>, <textarea> and <script> tags (including their spaces and line breaks), removing only the extra whitespace and comments between tags, so code blocks and scripts are never altered.",
 "标签未闭合检测是怎么工作的？": "How does unclosed tag detection work?",
 "检测采用简单的栈匹配：遇到开始标签入栈，遇到对应结束标签出栈。若栈中残留标签或遇到无法匹配的结束标签，会提示具体的未配对标签名。自闭合标签（如 <img>、<br>）与 void 元素不参与匹配。": "The detection uses simple stack matching: opening tags are pushed onto the stack and matching closing tags pop them off. If tags remain on the stack or a closing tag cannot be matched, the specific unpaired tag name is reported. Self-closing tags (such as <img> and <br>) and void elements do not participate in matching.",
 "HTML 实体转义有什么用？": "What is HTML entity escaping used for?",
 "在网页中展示 HTML 源码时，需将 <、>、&、\"、' 转为对应实体，否则会被浏览器当作标签解析。转义用于“显示代码”，反转义则用于把实体还原为原始字符。": "When displaying HTML source code on a web page, characters such as <, >, &, double quotes and single quotes must be converted to their corresponding entities, otherwise the browser will parse them as tags. Escape is used to display code, while unescape restores entities back to their original characters.",
 "多余的闭合标签：</": "Extra closing tag: </",
 "未闭合标签：<": "Unclosed tag: <",
 "标签检测：": "Tag check: ",
 "处理结果为空": "The result is empty",
