 "草稿会自动保存吗？": "Are drafts saved automatically?",
 "会。编辑内容会实时保存到浏览器localStorage，刷新或关闭页面后再次打开仍可恢复。点击“清除草稿”即可清空本地保存的内容。": "Yes. Your edits are saved to browser localStorage in real time and are restored when you open the page again after refreshing or closing it. Click Clear Draft to delete the locally saved content.",
 "导出的HTML文件包含样式吗？": "Does the exported HTML file include styles?",
 "包含。导出时会生成一份完整的HTML文档，内嵌基础排版样式（标题、列表、代码块、表格、引用等），用浏览器打开即可获得整洁的阅读效果。": "Yes. The export generates a complete HTML document with basic typography styles embedded (headings, lists, code blocks, tables, quotes, etc.), so opening it in a browser gives a clean reading experience.",
 "我的文档内容会被上传吗？": "Will my document be uploaded?",
