 "勾选后，转换结果会包含完整的HTML文档结构（&lt;!DOCTYPE html&gt;、head、meta 与内嵌基础排版样式），可直接保存为 .html 文件用浏览器打开；不勾选则只输出 body 内的 HTML 片段，方便嵌入现有页面。": "When checked, the conversion result includes the complete HTML document structure (&lt;!DOCTYPE html&gt;, head, meta and embedded basic typography styles), ready to save as a .html file and open in a browser. When unchecked, only the HTML fragment inside the body is output, which is convenient for embedding into existing pages.",
 "转换后的HTML安全吗？": "Is the converted HTML safe?",
 "Markdown本身支持原始HTML，转换会保留你写入的内容。由于完全在本地浏览器完成、不上传，适合处理自己的文档；若转换不可信来源的Markdown，请在插入网页前自行检查其中的脚本标签。": "Markdown natively supports raw HTML, so the conversion preserves whatever you write. Since everything is done locally in the browser with no upload, it is suitable for your own documents; if you convert Markdown from untrusted sources, please check it for script tags before inserting it into a web page.",
 "Markdown支持哪些常用语法？": "Which common syntaxes does Markdown support?",
 "常用语法包括标题（#）、强调（**粗体** / *斜体*）、列表（有序与无序）、链接与图片、行内与块级代码、表格以及引用（&gt;）。页面底部提供了完整速查表。": "Common syntaxes include headings (#), emphasis (**bold** / *italic*), lists (ordered and unordered), links and images, inline and block code, tables and quotes (&gt;). A complete cheat sheet is provided at the bottom of the page.",
