 "常用语法包括标题（#）、强调（**粗体** / *斜体*）、列表（有序与无序）、链接与图片、行内与块级代码、表格以及引用（>）。页面底部提供了完整速查表。": "Common syntaxes include headings (#), emphasis (**bold** / *italic*), lists (ordered and unordered), links and images, inline and block code, tables and quotes (>). A complete cheat sheet is provided at the bottom of the page.",
