 "已下载 .html 文件": ".html file downloaded",
 "# 标题示例\\n\\n这是一段 **加粗** 与 *斜体* 文本。\\n\\n- 项目一\\n- 项目二\\n\\n> 引用内容\\n\\n```js\\nconsole.log('hello');\\n```\\n\\n| 名称 | 说明 |\\n| --- | --- |\\n| A | 示例 |": "# Heading Example\\n\\nThis is a paragraph with **bold** and *italic* text.\\n\\n- Item 1\\n- Item 2\\n\\n> Quoted content\\n\\n```js\\nconsole.log('hello');\\n```\\n\\n| Name | Description |\\n| --- | --- |\\n| A | Example |",
 "去除空格 - 在线清理空白字符工具 | 在线工具大全": "Remove Spaces - Online Whitespace Cleaner | Online Tools",
 "免费在线去除空格工具，支持去首尾空白、去所有空格、压缩连续空格、去制表符、去换行、去空行、去全部空白等多种模式自由组合，实时处理并显示字符数与行数变化。": "Free online remove-spaces tool that supports trimming leading and trailing whitespace, removing all spaces, collapsing consecutive spaces, removing tabs, removing line breaks, removing empty lines, removing all whitespace and more. Freely combine modes, with real-time processing and live character and line counts.",
 "去除空格 - 在线清理空白字符工具": "Remove Spaces - Online Whitespace Cleaner",
 "在线去除空格工具，多种空白清理模式自由组合，实时处理并显示字符与行数变化。": "Online remove-spaces tool: freely combine multiple whitespace cleaning modes, with real-time processing and live character and line counts.",
 "在线清理空白字符工具，支持去首尾空白、去所有空格、压缩连续空格、去制表符、去换行、去空行、去全部空白等多种模式自由组合，实时处理并显示字符数与行数变化，所有计算本地完成。": "Online whitespace cleaner that supports trimming leading and trailing whitespace, removing all spaces, collapsing consecutive spaces, removing tabs, removing line breaks, removing empty lines, removing all whitespace and more. Freely combine modes, with real-time processing and live character and line counts. All calculations are done locally.",
 "清理模式（可多选，按列表顺序依次应用）": "Cleaning modes (multi-select, applied in list order)",
 "去首尾空白": "Trim Leading & Trailing Whitespace",
