 "行数：": "Lines: ",
 "原始文本": "Original Text",
 "输入需要清理空白的文本": "Enter the text you want to clean",
 "处理结果": "Result",
 "说明：勾选模式后将按“去首尾空白 → 制表符 → 压缩连续空格 → 去所有空格 → 去换行 → 去空行 → 去全部空白”的顺序依次处理。处理结果实时更新，并显示处理前后字符与行数变化。": "Note: after checking modes, the text is processed in this order: trim leading & trailing whitespace, tabs, collapse consecutive spaces, remove all spaces, remove line breaks, remove empty lines, remove all whitespace. The result updates in real time and shows the character and line counts before and after processing.",
 "多种模式可以同时勾选吗？": "Can multiple modes be checked at the same time?",
 "可以。所有模式都可勾选，处理会按固定顺序依次执行：先去首尾空白，再去除制表符、压缩连续空格、去除所有空格，最后处理换行与空行、去除全部空白。你可以按需组合。": "Yes. All modes can be checked and are applied in a fixed order: first trim leading and trailing whitespace, then remove tabs, collapse consecutive spaces and remove all spaces, and finally handle line breaks and empty lines, then remove all whitespace. Combine them as needed.",
 "“去全部空白”和“去所有空格”有什么区别？": "What is the difference between Remove all whitespace and Remove all spaces?",
 "“去所有空格”只删除半角空格字符；而“去全部空白”会删除所有空白字符，包括空格、制表符（Tab）、换行符等，常用于把多行文本压缩成一行无间隔内容。": "Remove all spaces only deletes half-width space characters, while Remove all whitespace deletes every whitespace character, including spaces, tabs (Tab) and line breaks. It is often used to compress multi-line text into a single line with no gaps.",
 "处理后字符和行数变化在哪里查看？": "Where can I see the character and line count changes after processing?",
 "处理结果上方会显示处理前后的字符数与行数对比，例如“1200 字符 → 1100 字符”，方便你直观了解清理效果。": "Above the result you will see the character and line counts before and after processing, for example 1200 characters to 1100 characters, so you can see the cleaning effect at a glance.",
 "在线去除空格工具，支持多种空白清理模式自由组合，实时处理并显示字符与行数变化。": "Online remove-spaces tool with freely combinable whitespace cleaning modes, real-time processing and live character and line counts.",
