 "大小写转换 - 在线英文字母与命名法转换工具 | 在线工具大全": "Case Converter - Online Letter Case & Naming Convention Tool | Online Tools",
 "免费在线大小写转换工具，支持全部大写、全部小写、每词首字母大写、句首大写、反转大小写，以及camelCase、PascalCase、snake_case、kebab-case、CONSTANT_CASE命名法转换，可多选按序组合。": "Free online case converter that supports UPPERCASE, lowercase, Title Case, Sentence case, swap case, and naming conventions including camelCase, PascalCase, snake_case, kebab-case and CONSTANT_CASE. Multi-select and combine in order.",
 "大小写转换 - 在线英文字母与命名法转换工具": "Case Converter - Online Letter Case & Naming Convention Tool",
 "在线大小写转换工具，支持多种大小写与命名法转换，可多选按序组合，实时预览、一键复制。": "Online case converter with multiple case and naming convention conversions. Multi-select and combine in order, with real-time preview and one-click copy.",
 "在线英文字母大小写与命名法转换工具，支持全部大写、全部小写、每词首字母大写、句首大写、反转大小写，以及 camelCase、PascalCase、snake_case、kebab-case、CONSTANT_CASE，可多选按序组合，实时预览。": "Online letter case and naming convention converter that supports UPPERCASE, lowercase, Title Case, Sentence case, swap case, plus camelCase, PascalCase, snake_case, kebab-case and CONSTANT_CASE. Multi-select and combine in order, with real-time preview.",
 "转换模式（可多选，按列表顺序依次应用）": "Conversion modes (multi-select, applied in list order)",
 "全部大写": "UPPERCASE",
 "全部小写": "lowercase",
 "每词首字母大写": "Title Case",
 "句首大写": "Sentence case",
 "反转大小写": "Swap case",
 "输入需要转换的英文文本，例如：hello world example": "Enter the English text to convert, e.g. hello world example",
 "转换结果": "Result",
 "交换输入输出": "Swap Input & Output",
 "说明：多种模式可同时勾选，将按“全部大写 → 全部小写 → 每词首字母 → 句首 → 反转 → camel → pascal → snake → kebab → 常量”的顺序依次应用。命名法模式会先按词拆分（含驼峰边界与符号分隔）再组合。": "Note: multiple modes can be checked at once and are applied in this order: UPPERCASE, lowercase, Title Case, Sentence case, swap case, camel, pascal, snake, kebab, CONSTANT_CASE. Naming convention modes first split the text into words (including camelCase boundaries and symbol separators) and then recombine them.",
 "可以把多种转换组合起来使用吗？": "Can multiple conversions be combined?",
 "可以。所有模式按钮都可多选，转换会按照页面列出的顺序依次应用。例如先选“全部小写”再选“snake_case”，可把任意文本规整为下划线命名。": "Yes. All mode buttons support multi-select and conversions are applied in the order listed on the page. For example, choosing lowercase first and then snake_case will normalize any text into underscore naming.",
 "camelCase 和 PascalCase 有什么区别？": "What is the difference between camelCase and PascalCase?",
 "camelCase（小驼峰）首单词首字母小写，后续单词首字母大写，例如 myVariableName；PascalCase（大驼峰）每个单词首字母都大写，例如 MyVariableName。两者常用于不同编程语言的命名约定。": "In camelCase (lower camel case), the first word starts lowercase and each subsequent word starts uppercase, e.g. myVariableName. In PascalCase (upper camel case), every word starts uppercase, e.g. MyVariableName. Both are common naming conventions in different programming languages.",
 "CONSTANT_CASE 是什么？": "What is CONSTANT_CASE?",
 "CONSTANT_CASE 又称大写常量命名，所有字母大写、单词之间用下划线分隔，例如 MAX_COUNT。常见于常量、枚举值或配置项的命名。": "CONSTANT_CASE, also known as upper snake case, uses all uppercase letters with words separated by underscores, e.g. MAX_COUNT. It is commonly used for naming constants, enum values or configuration items.",
 "在线大小写转换工具，支持多种大小写与命名法转换，可多选按序组合。": "Online case converter with multiple case and naming convention conversions. Multi-select and combine in order.",
 "全部大写/小写": "UPPERCASE / lowercase",
