 "文本对比 - 在线文本差异比较工具 | 在线工具大全": "Text Compare - Online Text Difference Tool | Online Tools",
 "免费在线文本对比工具，基于LCS算法逐行比较两段文本差异，删除行红色高亮、新增行绿色高亮并显示行号，支持忽略空白与忽略大小写，统计新增、删除、相同行数，可复制差异报告。": "Free online text comparison tool that compares two texts line by line using the LCS algorithm. Deleted lines are highlighted in red, added lines in green, with line numbers shown. Supports ignoring whitespace and ignoring case, counts added, deleted and unchanged lines, and lets you copy a difference report.",
 "文本对比 - 在线文本差异比较工具": "Text Compare - Online Text Difference Tool",
 "在线文本对比工具，逐行比较差异，红绿高亮、行号显示、忽略空白与大小写，可复制差异报告。": "Online text comparison tool: line-by-line difference highlighting in red and green, line numbers, options to ignore whitespace and case, and a copyable difference report.",
 "在线文本差异对比工具，基于 LCS 算法逐行比较两段文本，删除行红色高亮、新增行绿色高亮并显示行号，支持忽略空白与忽略大小写，统计新增、删除、相同行数，可复制差异报告。": "Online text difference tool that compares two texts line by line using the LCS algorithm. Deleted lines are highlighted in red, added lines in green, with line numbers shown. Supports ignoring whitespace and ignoring case, counts added, deleted and unchanged lines, and lets you copy a difference report.",
