 "对比结果": "Comparison Result",
 "输入两段文本并点击“开始对比”后，差异将显示在这里": "Enter two texts and click Compare; the differences will appear here",
 "文本对比采用什么算法？": "What algorithm does the text comparison use?",
 "采用 LCS（最长公共子序列）动态规划算法进行逐行比较，能够找出两段文本之间的最少修改路径，并以删除、新增、相同三种状态呈现差异。行数少于 2000 时实时计算。": "It uses the LCS (longest common subsequence) dynamic programming algorithm for line-by-line comparison, finding the minimum edit path between the two texts and presenting differences in three states: deleted, added and unchanged. Calculation runs in real time when there are fewer than 2000 lines.",
 "忽略空白和忽略大小写有什么用？": "What do Ignore whitespace differences and Ignore case do?",
 "开启“忽略空白差异”后，仅空格、制表符、换行数量不同但内容相同的行会被视为相同；开启“忽略大小写”后，仅字母大小写不同的行也会被视为相同，从而聚焦真正的内容变动。": "With Ignore whitespace differences enabled, lines with identical content but different numbers of spaces, tabs or line breaks are treated as the same. With Ignore case enabled, lines that differ only in letter case are also treated as the same, letting you focus on real content changes.",
 "可以导出或复制差异结果吗？": "Can I export or copy the difference result?",
 "可以。点击“复制差异报告”会把带 + / - 标记及统计信息的纯文本报告复制到剪贴板，方便粘贴到聊天、文档或提交记录中。": "Yes. Clicking Copy difference report copies a plain-text report with + and - markers and statistics to the clipboard, ready to paste into chats, documents or commit records.",
 "在线文本对比工具，基于LCS算法逐行比较差异，红绿高亮并显示行号。": "Online text comparison tool: line-by-line differences via the LCS algorithm, red and green highlighting with line numbers.",
