 "在线统计字数 - 实时统计中文字数/英文单词/字符数 | 在线工具大全": "Word Count - Real-time Chinese Character, English Word & Character Count | Online Tools",
 "免费在线字数统计工具，实时统计中文字数、英文单词数、字符数（含/不含空格）、行数、段落数、句子数，并估算阅读时长。支持粘贴文本或拖入 txt 文件，无需注册，即开即用。": "Free online word count tool that counts Chinese characters, English words, characters (with or without spaces), lines, paragraphs and sentences in real time, and estimates reading time. Paste text or drop in a .txt file - no registration required, ready to use instantly.",
 "在线统计字数 - 实时统计中文字数/英文单词/字符数": "Word Count - Real-time Chinese Character, English Word & Character Count",
 "免费在线字数统计工具，实时统计中文字数、英文单词数、字符数、行数、段落数、句子数，并估算阅读时长。": "Free online word count tool that counts Chinese characters, English words, characters, lines, paragraphs and sentences in real time, and estimates reading time.",
 "实时统计中文字数、英文单词数、字符数、行数、段落数与句子数，并估算阅读时长。支持粘贴文本或拖入 txt 文件，所有计算均在本地完成，不上传任何内容。": "Count Chinese characters, English words, characters, lines, paragraphs and sentences in real time, with an estimated reading time. Paste text or drop in a .txt file - all calculations are done locally and nothing is uploaded.",
 "复制统计结果": "Copy Statistics",
