 "0 分钟": "0 min",
 "预计阅读时长": "Estimated Reading Time",
 "说明：中文按「字」统计，英文按「词」统计；标点计入字符数、不计入字数；阅读时长按每分钟 300 字估算，仅供参考。所有数据仅在浏览器本地计算，不会上传服务器。": "Note: Chinese is counted by characters and English by words; punctuation is included in the character count but not in the word count. Reading time is estimated at 300 characters per minute and is for reference only. All data is calculated locally in your browser and never uploaded to a server.",
 "在线统计字数是怎么计算的？": "How is the word count calculated?",
 "中文字数按汉字逐字统计（一个汉字记 1 字），英文单词按连续字母或数字串统计（一个单词记 1 个），总字数为两者之和。字符数统计所有可见字符，可选择是否包含空格与换行。": "Chinese characters are counted one by one (each Han character counts as 1), and English words are counted as consecutive strings of letters or digits (each word counts as 1). The total is the sum of both. The character count includes all visible characters, with or without spaces and line breaks.",
 "统计结果会上传服务器吗？": "Are the statistics uploaded to a server?",
 "不会。所有统计均在您的浏览器本地完成，文本内容不会上传到任何服务器，请放心使用。": "No. All statistics are computed locally in your browser. Your text is never uploaded to any server, so you can use it with confidence.",
 "支持统计 txt 文件吗？": "Does it support counting .txt files?",
 "支持。您可以直接把 .txt 或 .md 文件拖拽到输入框中，工具会自动读取文件内容并进行统计，文件需小于 5MB。": "Yes. You can drag a .txt or .md file directly into the input box; the tool reads the file and counts it automatically. Files must be smaller than 5MB.",
 "阅读时长是怎么估算的？": "How is reading time estimated?",
 "按成年人中文阅读速度约每分钟 300 字估算，中英文混合内容按总字数折算，结果仅供参考。": "It is estimated at roughly 300 characters per minute, a typical adult Chinese reading speed; mixed Chinese and English content is converted by total word count. The result is for reference only.",
 "免费在线字数统计工具，实时统计中文字数、英文单词数、字符数（含/不含空格）、行数、段落数、句子数，并估算阅读时长。": "Free online word count tool that counts Chinese characters, English words, characters (with or without spaces), lines, paragraphs and sentences in real time, and estimates reading time.",
