 "字数统计是写作、排版和翻译工作中最常见的基础需求之一。": "Word count is one of the most basic needs in writing, typesetting and translation work.",
 "无论是学生党写论文、新媒体运营写文案，还是开发者写技术文档，": "Whether you are a student writing a paper, a social media manager writing copy, or a developer writing technical documentation,",
