 "进制转换 - 2/8/10/16及任意进制在线互转 | 在线工具大全": "Number Base Converter - Convert Between 2/8/10/16 and Any Base Online | Online Tools",
 "免费在线进制转换工具，支持二进制、八进制、十进制、十六进制及任意 2-36 进制互转，支持负数与超大数（BigInt），并可生成字节 HEX 视图，所有计算在浏览器本地完成。": "Free online number base converter supporting binary, octal, decimal, hexadecimal and any base from 2 to 36, with negative number and BigInt support, plus a byte HEX view. All calculations run locally in your browser.",
