 "如何输入十六进制、二进制数字？": "How do I enter hexadecimal or binary numbers?",
 "本工具按你选择的源进制解析。选「十六进制」时可输入 FF 或带前缀 0xFF；选「二进制」时可输入 1010 或带前缀 0b1010；选「八进制」可输入 17 或 0o17。超出该进制合法字符的输入会提示错误。": "The tool parses input according to the source base you select. Choose Hexadecimal and you can enter FF or 0xFF; choose Binary and you can enter 1010 or 0b1010; choose Octal and you can enter 17 or 0o17. Input containing characters that are invalid for the selected base will show an error.",
 "支持多大的数字？负数可以吗？": "How large can the numbers be? Are negative numbers supported?",
 "本工具使用 BigInt 进行任意精度整数运算，理论上仅受浏览器内存限制，可处理几十上百位的超大整数；同时支持以负号开头的负数。": "This tool uses BigInt for arbitrary-precision integer arithmetic. In theory it is limited only by browser memory, so it can handle very large integers with dozens or even hundreds of digits. Negative numbers starting with a minus sign are also supported.",
 "字节 HEX 视图是做什么的？": "What is the byte HEX view for?",
 "把一段文本按 UTF-8 编码成字节，并以两位十六进制一组的形式展示（如 Hello → 48 65 6C 6C 6F），常用于查看字符串的底层字节。也支持反向：粘贴 HEX 还原为文本。": "It encodes text into UTF-8 bytes and displays them as two-digit hexadecimal groups (e.g. Hello becomes 48 65 6C 6C 6F), which is useful for inspecting the underlying bytes of a string. The reverse is also supported: paste HEX to restore it as text.",
 "在线进制转换工具，支持二、八、十、十六进制及任意 2-36 进制互转，支持负数与超大数。": "Online number base converter supporting binary, octal, decimal, hexadecimal and any base from 2 to 36, with negative number and large integer support.",
