 "颜色转换 - HEX/RGB/HSL/HSV在线互转工具 | 在线工具大全": "Color Converter - HEX/RGB/HSL/HSV Online Tool | Online Tools",
 "免费在线颜色转换工具，支持取色器与 HEX、RGB、HSL、HSV 互转，实时预览，生成互补色、明色暗色变体及带透明度 rgba/hsla，附 Web 常用颜色速查表，计算在浏览器本地完成。": "Free online color converter with a color picker and HEX, RGB, HSL and HSV conversion. Features real-time preview, complementary colors, light and dark variants, rgba/hsla with opacity, plus a quick reference of common web colors. All calculations run locally in your browser.",
 "颜色转换 - HEX/RGB/HSL/HSV在线互转工具": "Color Converter - HEX/RGB/HSL/HSV Online Tool",
 "支持取色器与 HEX/RGB/HSL/HSV 互转、实时预览与衍生色的在线颜色转换工具。": "Online color converter with color picker, HEX/RGB/HSL/HSV conversion, real-time preview and derived colors.",
 "在线颜色转换工具，支持取色器与 HEX、RGB、HSL、HSV 四种格式互转，实时大图预览，生成互补色、明色暗色变体及带透明度 rgba/hsla，并附 Web 常用颜色速查表。": "Online color converter supporting conversion between HEX, RGB, HSL and HSV with a color picker, large real-time preview, complementary colors, light and dark variants, rgba/hsla with opacity, and a quick reference of common web colors.",
