 "HEX、RGB、HSL、HSV 有什么区别？": "What is the difference between HEX, RGB, HSL and HSV?",
 "HEX 与 RGB 本质相同，都用红绿蓝三通道表示颜色，HEX 是十六进制简写。HSL 用色相/饱和度/亮度，HSV 用色相/饱和度/明度，更符合人眼对颜色的直觉，便于调色。": "HEX and RGB are essentially the same: both represent colors with red, green and blue channels, and HEX is just a hexadecimal shorthand. HSL uses hue, saturation and lightness, while HSV uses hue, saturation and value. These models match human color perception more intuitively and make color adjustment easier.",
 "如何表示带透明度的颜色？": "How do I represent colors with transparency?",
 "在 RGB/HSL 后加一个 alpha 通道即可：rgba(r,g,b,a) 或 hsla(h,s,l,a)，a 取值范围 0~1。本工具提供透明度滑块并实时输出 rgba/hsla。": "Add an alpha channel to RGB or HSL: rgba(r,g,b,a) or hsla(h,s,l,a), where a ranges from 0 to 1. This tool provides an opacity slider and outputs rgba/hsla in real time.",
 "互补色是怎么算出来的？": "How is the complementary color calculated?",
 "在 HSL/HSV 色彩空间中，将色相旋转 180° 即可得到互补色，也就是色环上正对面的颜色，常用于配色对比。本工具还会给出明色、暗色变体。": "In the HSL/HSV color space, rotating the hue by 180 degrees gives the complementary color, which sits directly opposite on the color wheel and is often used for color contrast. This tool also provides light and dark variants.",
 "在线颜色转换工具，支持取色器与 HEX、RGB、HSL、HSV 互转及衍生色生成。": "Online color converter with color picker, HEX/RGB/HSL/HSV conversion and derived color generation.",
