 "数据大小转换 - 字节KB/MB/GB/TB/PB/EB在线换算 | 在线工具大全": "Data Size Converter - Convert Bytes KB/MB/GB/TB/PB/EB Online | Online Tools",
 "免费在线数据大小转换工具，支持 B/KB/MB/GB/TB/PB/EB 全单位实时换算，可一键切换 1024（KiB/MiB）与 1000（KB/MB）两种进制，附带常见文件大小趣味参照，计算在浏览器本地完成。": "Free online data size converter supporting real-time conversion between all units from B to EB, with one-click switching between the 1024 (KiB/MiB) and 1000 (KB/MB) bases, plus fun references for common file sizes. All calculations run locally in your browser.",
 "数据大小转换 - 字节KB/MB/GB/TB/PB/EB在线换算": "Data Size Converter - Convert Bytes KB/MB/GB/TB/PB/EB Online",
 "支持 B~EB 全单位实时换算、1024 与 1000 进制切换的在线数据大小转换工具，附带常见文件大小参照。": "Online data size converter supporting real-time conversion between all units from B to EB, with 1024 and 1000 base switching and common file size references.",
 "在线数据大小转换工具，支持 B、KB、MB、GB、TB、PB、EB 全单位实时换算，可一键切换 1024（KiB/MiB）与 1000（KB/MB）两种进制，输入任一单位即刷新全表。": "Online data size converter supporting real-time conversion between B, KB, MB, GB, TB, PB and EB, with one-click switching between the 1024 (KiB/MiB) and 1000 (KB/MB) bases. Enter a value in any unit and the whole table refreshes.",
