 "1024 进制和 1000 进制有什么区别？": "What is the difference between the 1024 and 1000 bases?",
 "计算机以 2 为底，1 KiB = 1024 B；而存储厂商与网络常用十进制，1 KB = 1000 B。同一数值用两种进制换算结果不同，这就是硬盘标称容量与电脑显示容量有差异的原因。本工具可一键切换。": "Computers work in powers of 2, so 1 KiB = 1024 B, while storage manufacturers and networks usually use the decimal system, where 1 KB = 1000 B. The same number converts differently under the two bases, which is why a hard drive's labeled capacity differs from the capacity shown on your computer. This tool lets you switch with one click.",
 "KB 和 KiB 是同一个意思吗？": "Do KB and KiB mean the same thing?",
 "严格来说不同：KB 是十进制千字节（1000 B），KiB 是二进制千比字节（1024 B）。日常口语常混用，但技术场景下应区分。本工具在 1024 进制下使用 KiB/MiB/GiB 等标注。": "Strictly speaking, no: KB is a decimal kilobyte (1000 B), while KiB is a binary kibibyte (1024 B). The two are often mixed up in everyday speech, but they should be distinguished in technical contexts. This tool uses KiB/MiB/GiB labels in the 1024 base.",
 "为什么硬盘标称 1TB 但电脑只显示约 931GB？": "Why does a hard drive labeled 1 TB show only about 931 GB on a computer?",
 "厂商按 1 TB = 1000 GB = 1,000,000,000,000 B 标注；操作系统按 1024 进制计算，1,000,000,000,000 / 1024 / 1024 / 1024 ≈ 931 GiB，显示为约 931 GB。两者数值一致，只是进制口径不同。": "Manufacturers label it as 1 TB = 1000 GB = 1,000,000,000,000 B, while the operating system calculates in the 1024 base: 1,000,000,000,000 / 1024 / 1024 / 1024 is about 931 GiB, displayed as roughly 931 GB. The values are consistent; only the base convention differs.",
 "在线数据大小转换工具，支持 B/KB/MB/GB/TB/PB/EB 全单位实时换算，可切换 1024 与 1000 进制。": "Online data size converter supporting real-time conversion between all units from B to EB, with switchable 1024 and 1000 bases.",
