 "时间戳的秒和毫秒如何区分？": "How do I tell seconds from milliseconds in a timestamp?",
 "Unix时间戳10位数字代表秒（自1970-01-01起的秒数），13位数字代表毫秒。本工具会自动识别位数：10位按秒解析，13位按毫秒解析，也可手动切换单位。": "A 10-digit Unix timestamp represents seconds (elapsed since 1970-01-01), while a 13-digit timestamp represents milliseconds. This tool automatically detects the length: 10 digits are parsed as seconds and 13 digits as milliseconds, and you can also switch units manually.",
 "本地时间、ISO 8601 和 UTC 有什么区别？": "What is the difference between local time, ISO 8601 and UTC?",
 "本地时间按你设备所在时区显示；ISO 8601 通常带有时区偏移（如 +08:00）；UTC 是协调世界时（零时区）的表示。三者描述的是同一时刻，只是展示口径不同。": "Local time is shown in your device's time zone; ISO 8601 usually includes a time zone offset (such as +08:00); UTC is Coordinated Universal Time (zero offset). All three describe the same moment, just in different formats.",
 "为什么同一个时间戳在不同时区显示不同？": "Why does the same timestamp show different times in different time zones?",
 "时间戳本身与时区无关，记录的是绝对时刻。显示成具体日期时间时需要结合时区，因此北京（东八区）与伦敦看到的可读时间不同，但底层时间戳一致。": "A timestamp itself is time zone independent and records an absolute moment. Converting it to a readable date-time requires a time zone, so Beijing (UTC+8) and London display different readable times even though the underlying timestamp is the same.",
 "在线Unix时间戳转换工具，支持秒/毫秒自动识别，本地时间、ISO 8601、UTC三种格式互转，提供实时时钟与快捷时间。": "Online Unix timestamp converter with automatic second/millisecond detection, conversion between local time, ISO 8601 and UTC, a real-time clock and quick time buttons.",
