 "单位换算 - 长度质量面积体积温度等在线换算器 | 在线工具大全": "Unit Converter - Length, Mass, Area, Volume, Temperature and More Online | Online Tools",
 "免费在线单位换算工具，支持长度、质量、面积、体积、温度、速度、时间、压力、功率、数据存储十大类，双向实时换算并给出全单位列表，一键复制结果，计算均在浏览器本地完成。": "Free online unit converter supporting ten categories: length, mass, area, volume, temperature, speed, time, pressure, power and data storage. Convert in both directions in real time, see results for all units, and copy with one click. All calculations run locally in your browser.",
 "单位换算 - 长度质量面积体积温度等在线换算器": "Unit Converter - Length, Mass, Area, Volume, Temperature and More Online",
 "支持十大类单位双向实时换算的在线单位换算工具，给出全单位列表，一键复制结果。": "Online unit converter supporting two-way real-time conversion across ten categories, with a full unit list and one-click copy.",
 "在线单位换算工具，覆盖长度、质量、面积、体积、温度、速度、时间、压力、功率、数据存储十大类，支持源单位与目标单位双向实时换算，并列出该数值在所有单位下的结果。": "Online unit converter covering ten categories: length, mass, area, volume, temperature, speed, time, pressure, power and data storage. Convert between source and target units in both directions in real time, and see the value in every unit.",
 "数值": "Value",
 "输入要换算的数值": "Enter the value to convert",
 "源单位": "Source Unit",
 "交换源/目标单位": "Swap Source/Target Units",
 "目标单位": "Target Unit",
 "该数值在所有单位下的结果": "Results for this value in all units",
 "温度为什么不能像长度一样直接乘系数？": "Why can temperature not be converted by simply multiplying a factor like length?",
 "摄氏、华氏、开尔文、兰氏之间存在偏移量（零点不同），不是简单的比例关系，必须使用专门的换算公式。本工具已内置这些公式，输入任意单位都能正确互转。": "Celsius, Fahrenheit, Kelvin and Rankine have offsets (different zero points), so they are not simple proportional relationships and require dedicated conversion formulas. This tool has these formulas built in, so any unit can be converted correctly.",
 "单位换算结果精度如何？": "How precise are the conversion results?",
 "结果按常用精度（最多约10位有效数字）显示，并自动去除多余的末尾零。极端量级下可能使用科学计数法，但误差极小，满足日常与工程估算需求。": "Results are shown at common precision (up to about 10 significant digits) with redundant trailing zeros removed automatically. Scientific notation may be used for extreme magnitudes, but the error is negligible for everyday and engineering estimates.",
 "数据存储换算用的是 1024 还是 1000？": "Does data storage conversion use 1024 or 1000?",
 "本工具的数据存储分类采用十进制（1 KB = 1000 B）用于通用换算；若需区分 KiB/MiB（1024 进制），请使用本站「数据大小转换」工具，可一键切换进制。": "The data storage category in this tool uses the decimal system (1 KB = 1000 B) for general conversion. If you need KiB/MiB (1024 base) distinctions, use the Data Size Converter tool on this site, which lets you switch bases with one click.",
 "在线单位换算工具，支持长度、质量、面积、体积、温度、速度、时间、压力、功率、数据存储十大类双向换算。": "Online unit converter supporting two-way conversion across ten categories: length, mass, area, volume, temperature, speed, time, pressure, power and data storage.",
