 "WKT几何解析 - WKT转GeoJSON与可视化预览 | 在线工具大全": "WKT Geometry Parser - WKT to GeoJSON with Visual Preview | Online Tools",
 "免费在线WKT几何解析工具，支持POINT、LINESTRING、POLYGON及其MULTI与GEOMETRYCOLLECTION类型，识别Z/M坐标，输出几何类型、坐标点数、边界框、坐标表与符合RFC 7946的GeoJSON，并提供SVG预览。所有解析本地完成。": "Free online WKT geometry parser supporting POINT, LINESTRING, POLYGON and their MULTI and GEOMETRYCOLLECTION variants, with Z/M coordinate recognition. It outputs the geometry type, coordinate count, bounding box, coordinate table and RFC 7946 compliant GeoJSON, plus an SVG preview. All parsing is done locally.",
 "WKT几何解析 - WKT转GeoJSON与可视化预览": "WKT Geometry Parser - WKT to GeoJSON with Visual Preview",
 "支持POINT/LINESTRING/POLYGON及MULTI与GEOMETRYCOLLECTION，识别Z/M坐标，输出GeoJSON并提供SVG预览。": "Supports POINT/LINESTRING/POLYGON with MULTI and GEOMETRYCOLLECTION variants, recognizes Z/M coordinates, outputs GeoJSON and provides an SVG preview.",
 "输入 Well-Known Text（WKT）几何文本，本地解析几何类型、坐标点数、嵌套层级与边界框 bbox，生成符合 RFC 7946 的 GeoJSON 并支持 SVG 可视化预览。支持 Z/M 维度标记，不上传任何数据。": "Enter Well-Known Text (WKT) geometry and parse the geometry type, coordinate count, nesting depth and bounding box locally, generate RFC 7946 compliant GeoJSON, and preview it as SVG. Z/M dimension markers are supported and no data is uploaded.",
 "WKT 文本": "WKT Text",
 "例如：POLYGON ((30 10, 40 40, 20 40, 10 20, 30 10))": "e.g. POLYGON ((30 10, 40 40, 20 40, 10 20, 30 10))",
