 "复制 GeoJSON": "Copy GeoJSON",
 "工具支持哪些 WKT 几何类型？": "Which WKT geometry types does the tool support?",
 "支持 POINT、LINESTRING、POLYGON、MULTIPOINT、MULTILINESTRING、MULTIPOLYGON 以及 GEOMETRYCOLLECTION。同时识别坐标后的 Z、M、ZM 维度标记（三维/带测量值），基础二维及常见三维写法均可正确解析。": "POINT, LINESTRING, POLYGON, MULTIPOINT, MULTILINESTRING, MULTIPOLYGON and GEOMETRYCOLLECTION are supported. Z, M and ZM dimension markers after coordinates (3D / measured values) are also recognized, so basic 2D and common 3D formats are parsed correctly.",
 "输出的 GeoJSON 符合规范吗？": "Is the output GeoJSON standards compliant?",
 "输出严格遵循 RFC 7946：包含 type、coordinates（或 geometries 用于几何集合）以及可选的顶层 bbox 字段。可直接用于地图库（如 Leaflet、Mapbox、OpenLayers）或地理数据处理流程。": "The output strictly follows RFC 7946: it includes type, coordinates (or geometries for geometry collections) and an optional top-level bbox field. It can be used directly with map libraries such as Leaflet, Mapbox and OpenLayers, or in geodata processing pipelines.",
 "输入格式错误会怎样提示？": "What happens if the input format is wrong?",
 "解析时会先做括号配平与坐标数值校验。若括号不匹配或坐标不是合法数字，会在错误提示中尽量给出出错位置，便于快速定位并修正 WKT 文本。": "Parsing first checks bracket balance and coordinate values. If brackets do not match or coordinates are not valid numbers, the error message will point to the approximate location so you can quickly find and fix the WKT text.",
 "在线WKT几何解析工具，支持POINT、LINESTRING、POLYGON及其MULTI与GEOMETRYCOLLECTION，识别Z/M坐标，输出GeoJSON并提供SVG预览。": "Online WKT geometry parser supporting POINT, LINESTRING, POLYGON and their MULTI and GEOMETRYCOLLECTION variants, with Z/M coordinate recognition, GeoJSON output and an SVG preview.",
