 "CSS圆角生成器 - 在线border-radius简写代码生成 | 在线工具大全": "CSS Border Radius Generator - Online border-radius Shorthand Code Generator | Online Tools",
 "免费在线CSS圆角生成器，支持四角独立圆角、椭圆圆角（水平/垂直双半径）与单位px/%切换，可视化实时预览并生成border-radius简写代码，含圆形、胶囊、叶形等创意预设。": "Free online CSS border-radius generator with independent corners, elliptical radii (horizontal/vertical dual values) and px/% unit switching. Preview changes live, generate border-radius shorthand code, and pick from creative presets such as circle, pill and leaf.",
 "CSS圆角生成器 - 在线border-radius简写代码生成": "CSS Border Radius Generator - Online border-radius Shorthand Code Generator",
 "支持四角独立、椭圆圆角与单位切换的在线CSS圆角生成器，实时预览并复制代码。": "Online CSS border-radius generator with independent corners, elliptical radii and unit switching, with live preview and one-click code copy.",
 "在线 CSS 圆角生成工具，支持四角独立圆角、椭圆圆角（水平/垂直双半径）与 px/% 单位切换，实时可视化预览并生成可直接复制的 border-radius 简写代码。": "Online CSS border radius generator supporting independent corners, elliptical radii (horizontal/vertical dual values) and px/% unit switching, with live visual preview and directly copyable border-radius shorthand code.",
 "高级模式（椭圆圆角 / 水平垂直双值）": "Advanced Mode (elliptical radius / separate horizontal and vertical values)",
 "复制 CSS": "Copy CSS",
 "圆角预览": "Radius Preview",
 "四角圆角": "Corner Radius",
 "椭圆圆角 · 垂直半径": "Elliptical Radius · Vertical Radius",
 "预览内容": "Preview Content",
 "纯色块": "Solid Block",
 "渐变块": "Gradient Block",
 "图片占位": "Image Placeholder",
 "文字卡片": "Text Card",
 "生成的 CSS": "Generated CSS",
 "创意预设": "Creative Presets",
 "说明：四个滑块依次对应左上、右上、右下、左下角。开启高级模式后可为每个角单独设置水平与垂直半径，生成如叶子、花瓣等椭圆圆角效果。": "Note: The four sliders correspond to the top-left, top-right, bottom-right and bottom-left corners in order. In advanced mode you can set the horizontal and vertical radius of each corner separately to create elliptical effects such as leaves and petals.",
 "border-radius 的简写顺序是怎样的？": "What is the shorthand order of border-radius?",
 "border-radius 四个值依次对应：左上、右上、右下、左下（顺时针）。若只写两个值，则第一个表示左上/右下、第二个表示右上/左下（对角相同）。椭圆圆角可用斜杠分隔水平与垂直半径，如 10px / 20px。": "The four values of border-radius correspond to top-left, top-right, bottom-right and bottom-left (clockwise). With only two values, the first applies to the top-left/bottom-right and the second to the top-right/bottom-left (diagonal corners match). For elliptical radii, separate the horizontal and vertical values with a slash, e.g. 10px / 20px.",
 "px 和 % 单位有什么区别？": "What is the difference between px and % units?",
 "px 是固定的像素半径，结果随容器尺寸固定；% 是相对圆角所在边的百分比，例如 50% 在正方形上得到正圆，在长方形上得到椭圆。需要响应式或正圆效果时优先使用 %。": "px is a fixed pixel radius that does not change with the container size, while % is a percentage relative to the side the radius sits on: for example, 50% yields a perfect circle on a square and an ellipse on a rectangle. Prefer % for responsive layouts or perfect circles.",
 "如何实现椭圆圆角（叶子、花瓣形）？": "How do I create elliptical corners (leaf or petal shapes)?",
 "使用斜杠语法分别指定水平半径和垂直半径，例如 border-radius: 50% 50% 50% 0 / 60% 60% 40% 40%。工具的高级模式可直接调节每个角的水平、垂直双值来生成这类效果。": "Use the slash syntax to specify the horizontal and vertical radii separately, e.g. border-radius: 50% 50% 50% 0 / 60% 60% 40% 40%. The advanced mode of this tool lets you adjust both values for each corner directly to create such effects.",
 "在线CSS圆角生成器，支持四角独立圆角、椭圆圆角与单位切换，实时预览并生成border-radius简写代码。": "Online CSS border-radius generator with independent corners, elliptical radii and unit switching, live preview and border-radius shorthand code generation.",
