 "免费在线CSS渐变生成器，支持线性、径向、圆锥渐变，可视化调节角度、形状、位置与多色标，实时预览并提供可直接复制的CSS代码，含多套热门渐变预设模板。": "Free online CSS gradient generator supporting linear, radial and conic gradients. Visually adjust the angle, shape, position and multiple color stops, preview in real time and copy ready-to-use CSS code, with a collection of popular gradient presets.",
