 "属性，直接粘贴到目标元素样式即可生效。": " property; paste it straight into the style of the target element to apply it.",
 "线性渐变和径向渐变有什么区别？": "What is the difference between linear and radial gradients?",
 "线性渐变沿一条直线方向过渡（可通过角度控制方向），适合营造斜向或上下过渡；径向渐变从中心向外呈圆形或椭圆形扩散，适合模拟光晕、按钮高光等效果。圆锥渐变则绕中心点旋转着色。": "A linear gradient transitions along a straight line (its direction is controlled by the angle), which suits diagonal or top-to-bottom transitions; a radial gradient spreads outward from the center as a circle or ellipse, ideal for glows and button highlights; a conic gradient sweeps its colors around the center point.",
 "生成的CSS代码如何直接使用？": "How do I use the generated CSS code directly?",
 "将工具生成的 background 属性复制后粘贴到目标元素的CSS规则中即可。绝大多数现代浏览器均原生支持 linear-gradient、radial-gradient 与 conic-gradient。": "Copy the generated background property and paste it into the CSS rule of the target element. Virtually all modern browsers natively support linear-gradient, radial-gradient and conic-gradient.",
 "可以设置多少个颜色停靠点？": "How many color stops can I set?",
 "颜色停靠点数量没有固定上限，工具默认提供两个，可随时点击“添加色标”增加，也可以删除多余色标，最少保留两个以保证渐变有效。": "There is no fixed limit on the number of color stops. The tool provides two by default; click Add Color Stop at any time to add more, or delete extra stops. Keep at least two for a valid gradient.",
 "在线CSS渐变生成器，支持线性、径向、圆锥渐变，可视化调节并实时生成可复制的CSS代码。": "Online CSS gradient generator supporting linear, radial and conic gradients, with visual adjustment and real-time generation of copyable CSS code.",
