 "Hash生成器 - MD5/SHA1/SHA256/SHA512在线哈希计算 | 在线工具大全": "Hash Generator - Online MD5/SHA1/SHA256/SHA512 Hash Calculator | Online Tools",
 "免费在线Hash生成器，支持 MD5、SHA1、SHA256、SHA384、SHA512 文本与文件哈希计算，以及 HMAC 签名，本地计算不联网，支持大小写切换与一键复制，所有数据均在浏览器内处理。": "Free online hash generator supporting MD5, SHA1, SHA256, SHA384 and SHA512 hashing of text and files, plus HMAC signing. Everything is computed locally with no network access, with uppercase/lowercase switching and one-click copy; all data stays in your browser.",
 "Hash生成器 - MD5/SHA1/SHA256/SHA512在线哈希计算": "Hash Generator - Online MD5/SHA1/SHA256/SHA512 Hash Calculator",
 "支持 MD5、SHA1、SHA256、SHA384、SHA512 与 HMAC 的在线哈希计算工具，本地计算不联网。": "Online hash calculator supporting MD5, SHA1, SHA256, SHA384, SHA512 and HMAC, computed locally with no network access.",
 "在线哈希计算工具，支持 MD5、SHA1、SHA256、SHA384、SHA512 与 HMAC 签名，所有计算均在浏览器本地完成，不会上传任何数据。": "Online hash calculator supporting MD5, SHA1, SHA256, SHA384, SHA512 and HMAC signing. All computation is done locally in your browser and no data is ever uploaded.",
 "哈希算法": "Hash Algorithm",
