 "或 https 访问以启用全部功能。": " or https to enable all features.",
 "计算结果": "Result",
 "在上方输入内容后点击「立即计算」。": "Enter content above and click Calculate Now.",
 "隐私说明：": "Privacy notice:",
 "无论是文本还是文件，所有哈希运算都在你的浏览器本地完成，文件不会上传到任何服务器。对于大文件仅读取其内容到内存计算，关闭页面后即消失。": " Whether text or files, all hashing is performed locally in your browser and files are never uploaded to any server. Large files are only read into memory for the computation and disappear once you close the page.",
 "为什么 SHA 系列在本地双击打开（file://）时无法计算？": "Why does the SHA family fail when the file is opened directly (file://)?",
 "SHA 系列使用浏览器 Web Crypto 接口（crypto.subtle），该接口仅在安全上下文中可用（https 或 http://localhost）。如果你直接双击打开网页（地址栏为 file://），浏览器会禁用 crypto.subtle。解决办法是通过本地服务器访问，例如在目录内执行 python -m http.server 后用 http://localhost 打开。": "The SHA family uses the browser Web Crypto API (crypto.subtle), which is only available in secure contexts (https or http://localhost). If you open the file directly by double-clicking it (the address bar shows file://), the browser disables crypto.subtle. The solution is to access it through a local server, for example run python -m http.server inside the directory and then open http://localhost.",
 "MD5 安全吗？还能用来做什么？": "Is MD5 safe? What can it still be used for?",
 "MD5 已被证明存在碰撞漏洞，不可用于安全签名或密码存储，但依然适合做普通文件完整性校验（如下载文件比对）或非安全场景的摘要。本工具的 MD5 为纯 JavaScript 实现，无需任何外部库。": "MD5 has proven collision vulnerabilities and must not be used for security signatures or password storage, but it is still suitable for ordinary file integrity checks (such as comparing downloaded files) or non-security digests. The MD5 in this tool is a pure JavaScript implementation that requires no external libraries.",
 "HMAC 和普通的哈希有什么区别？": "What is the difference between HMAC and a regular hash?",
 "HMAC（基于哈希的消息认证码）在哈希计算中引入了密钥，只有持有相同密钥的双方才能验证数据完整性，可防止篡改。普通哈希没有密钥，任何人都能重新计算。HMAC 常用于接口签名、请求校验等场景。": "HMAC (hash-based message authentication code) introduces a key into the hash computation, so only parties holding the same key can verify data integrity, which prevents tampering. A regular hash has no key and anyone can recompute it. HMAC is commonly used for API signing and request verification.",
 "在线哈希计算工具，支持 MD5、SHA1、SHA256、SHA384、SHA512 与 HMAC，本地计算不联网。": "Online hash calculator supporting MD5, SHA1, SHA256, SHA384, SHA512 and HMAC, computed locally with no network access.",
