 "图片Base64转换 - 在线图片转Base64编码/还原工具 | 在线工具大全": "Image to Base64 - Online Image Base64 Encoder/Decoder | Online Tools",
 "免费在线图片Base64转换工具，支持选择或拖入图片一键转为DataURL、纯Base64、CSS背景与HTML代码，并在浏览器本地还原Base64为图片预览与下载，全部处理不上传服务器。": "Free online image Base64 converter. Choose or drop an image to convert it to a DataURL, pure Base64, CSS background or HTML code in one click, and decode Base64 back to an image for preview and download locally in your browser. Nothing is ever uploaded to a server.",
 "图片Base64转换 - 在线图片转Base64编码/还原工具": "Image to Base64 - Online Image Base64 Encoder/Decoder",
 "支持图片转Base64多格式输出与Base64还原图片的在线工具，完全本地处理。": "Online tool for converting images to Base64 in multiple output formats and decoding Base64 back into images, fully processed locally.",
 "在线图片转 Base64 工具，支持选择或拖入图片，一键转换为 DataURL、纯 Base64、CSS 背景与 HTML 代码，并可将 Base64 反向还原为图片预览与下载，全程本地处理不上传。": "Online image to Base64 tool. Choose or drop an image to convert it to a DataURL, pure Base64, CSS background or HTML code in one click, and decode Base64 back into image previews and downloads. Everything is processed locally and never uploaded.",
