 "粘贴图片的 Base64 或完整 DataURL，工具将自动还原为图片": "Paste the Base64 of an image or a full DataURL and the tool will decode it back into an image",
 "还原图片": "Decode Image",
 "还原图片预览": "Decoded Image Preview",
 "图片转成Base64有什么用处？": "What is the point of converting images to Base64?",
 "Base64 可将图片直接内嵌进 HTML、CSS 或 JSON 中，减少小图标或多图场景下的额外网络请求，便于单文件分享与离线展示。代价是体积会比原文件大约增加 33%。": "Base64 can embed images directly into HTML, CSS or JSON, cutting extra network requests for small icons or multi-image pages and making single-file sharing and offline display easier. The trade-off is that the size grows by roughly 33% over the original file.",
 "转换过程会泄露我的图片吗？": "Could my images be leaked during conversion?",
 "不会。所有读取、编码与还原均在浏览器本地通过 FileReader 完成，图片不会上传到任何服务器，适合处理含有敏感信息的图像。": "No. All reading, encoding and decoding is done locally in your browser via FileReader; images are never uploaded to any server, so this is suitable for sensitive images.",
 "粘贴的Base64如何判断图片类型？": "How does the tool determine the image type from pasted Base64?",
 "若粘贴内容以 data: 开头则直接按其中的 MIME 类型处理；纯 Base64 时工具会根据文件头特征自动识别 PNG、JPEG、GIF、WEBP 等常见格式，识别失败则按 PNG 处理并给出提示。": "If the pasted content starts with data:, the MIME type inside it is used directly; for pure Base64, the tool automatically recognizes common formats such as PNG, JPEG, GIF and WEBP from the file header. If recognition fails, it falls back to PNG and shows a notice.",
 "在线图片Base64转换工具，支持图片转DataURL、纯Base64、CSS与HTML代码，并可反向还原Base64为图片。": "Online image Base64 converter supporting DataURL, pure Base64, CSS and HTML output, plus decoding Base64 back into images.",
