 "图片压缩 - 在线图片体积压缩/JPEG/WebP/PNG工具 | 在线工具大全": "Image Compression - Online JPEG/WebP/PNG Image Size Compressor | Online Tools",
 "免费在线图片压缩工具，支持 JPEG、WebP、PNG 格式，可通过质量、最大宽度限制进行有损或无损压缩，实时对比原图与压缩后效果并显示压缩率，所有处理均在浏览器本地完成。": "Free online image compression tool supporting JPEG, WebP and PNG. Compress lossily or losslessly via the quality and max width settings, compare the original and compressed results in real time with the compression ratio shown. All processing is done locally in your browser.",
 "图片压缩 - 在线图片体积压缩/JPEG/WebP/PNG工具": "Image Compression - Online JPEG/WebP/PNG Image Size Compressor",
 "支持质量与最大宽度调节的在线图片压缩工具，实时对比并下载压缩结果。": "Online image compression tool with quality and max width controls, real-time comparison and download of the compressed result.",
 "在线图片压缩工具，支持 JPEG、WebP、PNG 格式，通过质量与最大宽度限制压缩图片，实时对比原图与压缩后效果并显示压缩率，所有处理均在浏览器本地完成。": "Online image compression tool supporting JPEG, WebP and PNG. Compress images via the quality and max width limits, compare the original and compressed results in real time with the compression ratio shown. All processing is done locally in your browser.",
 "压缩质量：": "Quality: ",
 "最大宽度（px，0 表示不限制）": "Max Width (px, 0 means no limit)",
 "压缩图片": "Compress Image",
 "下载结果": "Download Result",
 "原图": "Original",
 "压缩后": "Compressed",
 "说明：PNG 为无损压缩，质量滑块对其无效，主要通过“最大宽度”缩小尺寸来减小体积；JPEG/WebP 为有损压缩，质量越低体积越小但画质损失越多。压缩在浏览器本地通过 Canvas 完成，图片不会上传。": "Note: PNG is lossless, so the quality slider has no effect on it and the size is reduced mainly by lowering Max Width; JPEG/WebP are lossy, where lower quality means smaller files but more quality loss. Compression runs locally in your browser via Canvas and images are never uploaded.",
 "为什么选 WebP 通常比 JPEG 更小？": "Why is WebP usually smaller than JPEG?",
 "WebP 采用更现代的编码算法，在相同观感下往往比 JPEG 体积更小，非常适合网页图片优化。但部分老旧浏览器对 WebP 支持有限，发布前请确认目标环境兼容性。": "WebP uses a more modern encoding algorithm and is often smaller than JPEG at similar visual quality, making it ideal for web image optimization. However, some older browsers have limited WebP support, so confirm compatibility with your target environment before publishing.",
 "最大宽度限制有什么作用？": "What does the max width limit do?",
 "限制最大宽度会按原始比例等比缩小图片尺寸，这是降低体积最有效的手段之一。例如将 4000px 宽的原图缩到 1600px，像素量大幅减少，文件体积也会明显下降。": "Limiting the max width scales the image down proportionally, which is one of the most effective ways to reduce file size. For example, scaling a 4000px-wide original down to 1600px drastically cuts the pixel count and noticeably shrinks the file.",
 "压缩后的图片会损失清晰度吗？": "Does compression cost image sharpness?",
 "JPEG 与 WebP 为有损压缩，质量越低、尺寸越小，损失越明显；PNG 为无损压缩，主要通过减少尺寸来缩小体积，不会引入画质损失，但压缩空间相对有限。": "JPEG and WebP are lossy: the lower the quality and the smaller the size, the more noticeable the loss. PNG is lossless and mainly shrinks the file by reducing dimensions, introducing no quality loss, but it offers relatively limited compression room.",
 "在线图片压缩工具，支持JPEG、WebP、PNG格式，通过质量与最大宽度调节进行压缩并对比结果。": "Online image compression tool supporting JPEG, WebP and PNG, with quality and max width controls and result comparison.",
 "JPEG/WebP/PNG压缩": "JPEG/WebP/PNG Compression",
