 "JWT签名验证 - 在线 JWT 校验与解析工具 | 在线工具大全": "JWT Signature Verification - Online JWT Validation and Parsing Tool | Online Tools",
 "免费在线 JWT 签名验证与解析工具，支持 HS256/384/512 与 RS256/384/512，自动识别算法，校验签名是否通过，并解析 Header 与 Payload 标准字段，所有计算均在浏览器本地完成，不会上传。": "Free online JWT signature verification and parsing tool supporting HS256/384/512 and RS256/384/512. It auto-detects the algorithm, verifies whether the signature passes, and parses the standard Header and Payload fields. All computation is done locally in your browser and nothing is uploaded.",
 "JWT签名验证 - 在线 JWT 校验与解析工具": "JWT Signature Verification - Online JWT Validation and Parsing Tool",
 "支持 HS256/384/512 与 RS256/384/512 的在线 JWT 校验与解析工具，所有计算均在本地完成。": "Online JWT validation and parsing tool supporting HS256/384/512 and RS256/384/512, with all computation done locally.",
 "在线 JWT 签名验证与解析工具，支持 HS256/384/512 与 RS256/384/512，自动识别算法并校验签名，解析 Header 与 Payload，所有计算均在浏览器本地完成，不会上传。": "Online JWT signature verification and parsing tool supporting HS256/384/512 and RS256/384/512, with automatic algorithm detection, signature verification and Header/Payload parsing. All computation is done locally in your browser and nothing is uploaded.",
 "JWT（三段式，以 . 分隔）": "JWT (three parts separated by .)",
 "粘贴完整的 JWT，例如：eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIn0.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c": "Paste a complete JWT, e.g. eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIn0.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c",
 "密钥（HMAC secret）": "Key (HMAC secret)",
 "HS* 算法填写共享密钥（文本）；RS* 算法填写 RSA 公钥 PEM": "For HS* algorithms enter the shared secret (text); for RS* algorithms enter the RSA public key in PEM",
 "检测到算法后会自动提示应填写的内容。": "The required input will be shown automatically once an algorithm is detected.",
 "验证签名": "Verify Signature",
 "⚠️ 当前页面处于非安全上下文（file:// 等），浏览器禁用了 Web Crypto 接口（crypto.subtle），无法执行签名验证。请通过本地服务器以": "⚠️ This page is in a non-secure context (file:// etc.), so the browser has disabled the Web Crypto API (crypto.subtle) and signature verification cannot run. Please access this tool via a local server over ",
 "或 https 访问本工具。": " or https.",
 "JWT 与密钥仅在你的浏览器本地参与计算，不会上传到任何服务器。对称签名（HS*）使用同一密钥验证；非对称签名（RS*）只需提供公钥即可验证私钥签名。": " The JWT and key are only used for computation locally in your browser and are never uploaded to any server. Symmetric signatures (HS*) are verified with the same key; asymmetric signatures (RS*) only require the public key to verify a private-key signature.",
 "等待验证": "Waiting to verify",
 "Header（头部）": "Header",
 "Payload（载荷）": "Payload",
 "粘贴 JWT 并填写密钥后，点击「验证签名」查看结果。": "Paste a JWT and enter the key, then click Verify Signature to see the result.",
 "对称签名（HS*）和非对称签名（RS*）有什么区别？": "What is the difference between symmetric (HS*) and asymmetric (RS*) signatures?",
 "HS256/384/512 使用同一个密钥（secret）进行签名与验证，签发方和验证方必须共享密钥，常见于内部服务。RS256/384/512 使用一对 RSA 密钥：私钥签名、公钥验证，公钥可以公开分发，验证方无需持有私钥，更适合多方协作或对外暴露。本工具对 RS* 只需提供公钥即可验证。": "HS256/384/512 sign and verify with the same secret, so the issuer and the verifier must share it; these are common for internal services. RS256/384/512 use a pair of RSA keys: the private key signs and the public key verifies. The public key can be distributed openly and verifiers never need the private key, which suits multi-party collaboration or public exposure. For RS*, this tool only needs the public key to verify.",
 "为什么必须通过 http://localhost 或 https 才能验证？": "Why is http://localhost or https required for verification?",
 "JWT 验证依赖浏览器 Web Crypto 接口（crypto.subtle），该接口仅在安全上下文（https 或 http://localhost）中可用。直接双击打开（file://）时浏览器会禁用该接口，工具会提示相关错误。请通过本地服务器访问。": "JWT verification relies on the browser Web Crypto API (crypto.subtle), which is only available in secure contexts (https or http://localhost). When you open the file directly by double-clicking it (file://), the browser disables this API and the tool shows a related error. Please access it through a local server.",
 "验证“通过”是否代表令牌有效且未过期？": "Does a passing verification mean the token is valid and not expired?",
 "“通过”仅表示签名正确、确实由持有对应密钥的一方签发，不代表令牌未过期或未生效。过期（exp）、生效时间（nbf）等声明需要业务系统自行校验，本工具会展示这些字段供你查看，但不会自动判定业务有效性。": "A pass only means the signature is correct and the token was indeed issued by a party holding the corresponding key; it does not mean the token is unexpired or already active. Claims such as exp (expiration) and nbf (not before) must be checked by your own system. This tool displays these fields for you to inspect but does not judge business validity automatically.",
 "在线 JWT 签名验证与解析工具，支持 HS/RSA 系列算法，所有计算在本地完成。": "Online JWT signature verification and parsing tool supporting the HS/RSA algorithm families, with all computation done locally.",
