 "密码生成器 - 随机强密码批量生成工具 | 在线工具大全": "Password Generator - Random Strong Password Batch Generator | Online Tools",
 "免费在线密码生成器，使用浏览器 crypto 安全随机数批量生成高强度密码，支持大小写字母、数字、符号与排除易混字符，可自定义长度并一键复制或下载，所有计算均在本地完成。": "Free online password generator that uses the browser crypto secure random number generator to batch-generate strong passwords. Supports uppercase and lowercase letters, digits, symbols and look-alike character exclusion, with custom lengths and one-click copy or download. All computation is done locally.",
 "密码生成器 - 随机强密码批量生成工具": "Password Generator - Random Strong Password Batch Generator",
 "使用浏览器 crypto 安全随机数批量生成高强度密码，支持自定义字符集与长度，所有计算均在本地完成。": "Batch-generate strong passwords with the browser crypto secure random number generator, with custom character sets and lengths. All computation is done locally.",
 "使用浏览器内置的 crypto 密码学安全随机数，批量生成高强度随机密码，支持自定义长度与字符集，所有计算均在本地完成，不会上传。": "Uses the browser built-in cryptographically secure crypto random numbers to batch-generate strong random passwords with custom lengths and character sets. All computation is done locally and nothing is uploaded.",
