 "字符池：62": "Character pool: 62",
 "所有密码仅在你的浏览器本地生成，不会经过任何网络传输或服务器存储。建议为不同网站使用不同密码，并配合密码管理器（如 Bitwarden、1Password）统一保管，避免使用生日、电话号码等可被猜测的信息。": "All passwords are generated locally in your browser and never travel over the network or get stored on a server. Use a different password for each website, keep them in a password manager (such as Bitwarden or 1Password), and avoid guessable information such as birthdays or phone numbers.",
 "复制全部": "Copy All",
 "点击「生成密码」开始创建随机密码。": "Click Generate Passwords to start creating random passwords.",
 "这个密码生成器的随机性安全吗？": "Is the randomness of this password generator secure?",
 "本工具使用浏览器内置的 crypto.getRandomValues 密码学安全随机数生成器，并采用拒绝采样法避免分布偏差，安全性远高于 Math.random()。所有密码仅在你的设备上生成，不会上传到任何服务器。": "This tool uses the browser built-in cryptographically secure random number generator crypto.getRandomValues with rejection sampling to avoid distribution bias, making it far safer than Math.random(). All passwords are generated on your device only and are never uploaded to any server.",
 "什么是“排除易混字符”？": "What does Exclude look-alike characters mean?",
 "易混字符指视觉上容易混淆的符号，如 0 与 O、1 与 l 与 I、以及 |`'\";: 等。勾选后会从字符集中剔除这些字符，生成的密码更适合人工抄写或口述，但不建议用于机器自动验证的场景。": "Look-alike characters are symbols that are easily confused visually, such as 0 and O, 1 and l and I, as well as the vertical bar, backtick, single and double quotes, semicolon and colon. When checked, these characters are removed from the character set, making the generated passwords easier to copy by hand or read aloud, though this is not recommended for machine auto-verification.",
 "多长的密码才足够安全？": "How long does a password need to be to be secure?",
 "一般建议至少 12 位且包含多种字符类型，重要账户推荐 16 位以上。本工具会按字符池大小估算熵值，熵越高越安全。请为每个站点使用不同的密码，并配合密码管理器保存。": "As a rule, use at least 12 characters with multiple character types, and 16 or more for important accounts. This tool estimates entropy from the character pool size; the higher the entropy, the safer the password. Please use a different password for each site and keep them in a password manager.",
 "在线密码生成器，使用浏览器 crypto 安全随机数批量生成高强度密码，支持自定义长度与字符集。": "Online password generator that batch-generates strong passwords using browser crypto secure random numbers, with custom lengths and character sets.",
