 "批量生成 1-100 个": "Batch generation of 1-100",
 "易混字符指视觉上容易混淆的符号，如 0 与 O、1 与 l 与 I，以及竖线、反引号、单双引号等。勾选后会从字符集中剔除这些字符，生成的密码更适合人工抄写或口述，但不建议用于机器自动验证的场景。": "Look-alike characters are symbols that are easily confused visually, such as 0 and O, 1 and l and I, as well as the vertical bar, backtick and single or double quotes. When checked, these characters are removed from the character set, making the generated passwords easier to copy by hand or read aloud, though this is not recommended for machine auto-verification.",
