 "密码强度检测 - 在线密码安全性分析与破解时间估算 | 在线工具大全": "Password Strength Checker - Online Password Security Analysis and Crack Time Estimation | Online Tools",
 "免费在线密码强度检测工具，实时分析密码长度、字符种类、重复模式、连续序列与常见弱密码，估算熵值与破解时间，给出改进建议，所有检测均在浏览器本地完成，密码不会上传。": "Free online password strength checker that analyzes length, character variety, repeated patterns, sequential runs and common weak passwords in real time, estimates entropy and crack time, and offers improvement suggestions. All checks run locally in your browser and passwords are never uploaded.",
 "密码强度检测 - 在线密码安全性分析与破解时间估算": "Password Strength Checker - Online Password Security Analysis and Crack Time Estimation",
 "实时分析密码强度，估算熵值与破解时间，给出改进建议，所有检测均在本地完成。": "Analyze password strength in real time, estimate entropy and crack time, and get improvement suggestions. All checks are done locally.",
 "在线密码安全性分析工具，实时检测密码长度、字符种类、重复模式、连续序列与常见弱密码，估算熵值与破解时间，并给出改进建议。纯本地检测，密码不会上传。": "Online password security analyzer that detects length, character variety, repeated patterns, sequential runs and common weak passwords in real time, estimates entropy and crack time, and offers improvement suggestions. Fully local detection; passwords are never uploaded.",
