 "这个工具会保存或上传我输入的密码吗？": "Does this tool save or upload the password I enter?",
 "不会。所有检测都在你的浏览器本地通过 JavaScript 完成，密码既不会上传到任何服务器，也不会被写入本地存储或 Cookie。你甚至可以断开网络后使用。检测完成后建议清空输入框。": "No. All checks are performed locally in your browser via JavaScript; the password is neither uploaded to any server nor written to local storage or cookies. You can even use it with the network disconnected. Clearing the input box after checking is recommended.",
 "熵值（bits）代表什么？": "What does entropy (bits) mean?",
 "熵值衡量密码的随机性，单位为 bit。粗略地说，熵 = 长度 × log2(字符池大小)。熵越高，暴力破解所需尝试次数越多。一般 60 bit 以上算较强，128 bit 以上极强。注意本工具还会根据重复、连续序列等模式扣除有效熵。": "Entropy measures the randomness of a password, in bits. Roughly speaking, entropy = length × log2(character pool size). The higher the entropy, the more attempts a brute-force attack needs. Above 60 bits is generally considered strong and above 128 bits extremely strong. Note that this tool also deducts effective entropy for patterns such as repeats and sequential runs.",
 "破解时间估算准确吗？": "Is the crack time estimate accurate?",
 "估算基于假设攻击者的每秒猜测速率：离线快哈希约 100 亿次/秒、离线慢哈希（如 bcrypt）约 1 万次/秒、在线爆破约 100 次/小时。结果仅作安全参考，真实情况取决于攻击者的算力与目标防护策略。": "The estimate assumes attacker guess rates: offline fast hashing around 10 billion per second, offline slow hashing (e.g. bcrypt) around 10 thousand per second, and online brute force around 100 per hour. The results are for security reference only; the reality depends on the attacker's computing power and the target's protection strategy.",
 "在线密码强度检测工具，实时分析密码安全性并估算破解时间，所有检测在本地完成。": "Online password strength checker that analyzes password security and estimates crack time in real time, with all checks done locally.",
