 "说明：二维码完全在本地浏览器生成，不会上传任何内容。颜色支持点击取色器或直接输入 HEX 值（如 #1e40af）；边距会在二维码四周留出白色的安静区，有助于提高扫码成功率。": "Note: QR codes are generated entirely in your local browser and no content is uploaded. Colors can be set with the color picker or by typing a HEX value directly (e.g. #1e40af); the margin leaves a white quiet zone around the QR code, which helps improve scan success rates.",
 "二维码的容错级别有什么作用？": "What does the QR code error correction level do?",
 "容错级别决定二维码被遮挡或污损后仍能扫描的概率。L约可遮挡7%、M约15%、Q约25%、H约30%。内容较多或需印刷在不平整表面时建议使用较高容错级别。": "The error correction level determines how likely a QR code remains scannable after being obscured or damaged. L tolerates about 7% damage, M about 15%, Q about 25% and H about 30%. Use a higher error correction level when there is a lot of content or when printing on uneven surfaces.",
 "生成的二维码可以用于商业用途吗？": "Can the generated QR codes be used commercially?",
 "可以。二维码本身不收取费用，本工具完全在浏览器本地生成，不收集、不上传任何内容，生成结果可自由用于商业或个人场景。": "Yes. QR codes themselves carry no fee; this tool generates them entirely in your local browser and neither collects nor uploads any content. The results can be freely used for commercial or personal purposes.",
 "二维码尺寸越大越清晰吗？": "Is a bigger QR code always clearer?",
 "清晰度主要取决于内容密度与打印分辨率，而非单纯尺寸。内容越多模块越密，建议适当提高尺寸并设置一定边距，以保证扫码设备稳定识别。": "Clarity depends mainly on content density and print resolution rather than size alone. More content means denser modules, so it is recommended to increase the size appropriately and set a margin to ensure reliable scanning.",
