 "Token生成器 - 随机密钥/API Key/令牌在线生成 | 在线工具大全": "Token Generator - Online Random Secret/API Key/Token Generator | Online Tools",
 "免费在线Token生成器，使用浏览器 crypto 安全随机数生成随机令牌、密钥与 API Key，支持 Hex、Base64、Base64URL 多种格式与批量生成，所有计算均在本地完成，不会上传。": "Free online token generator that uses browser crypto secure random numbers to generate random tokens, secrets and API keys, with Hex, Base64 and Base64URL formats and batch generation. All computation is done locally and nothing is uploaded.",
 "Token生成器 - 随机密钥/API Key/令牌在线生成": "Token Generator - Online Random Secret/API Key/Token Generator",
 "使用浏览器 crypto 安全随机数生成随机令牌、密钥与 API Key，支持 Hex、Base64、Base64URL 格式。": "Generate random tokens, secrets and API keys with browser crypto secure random numbers, in Hex, Base64 and Base64URL formats.",
 "在线随机令牌/密钥/API Key 生成工具，使用浏览器 crypto 安全随机数生成，支持 Hex、Base64、Base64URL 多种格式与批量生成，所有计算均在本地完成，不会上传。": "Online random token/secret/API key generator using browser crypto secure random numbers, supporting Hex, Base64 and Base64URL formats and batch generation. All computation is done locally and nothing is uploaded.",
 "长度（字节，16-128）": "Length (bytes, 16-128)",
 "数量（1-100）": "Quantity (1-100)",
 "生成 Token": "Generate Token",
 "所有 Token 仅在你的浏览器本地生成，不会经过任何网络传输或服务器存储。生成的密钥请妥善保存，一旦泄露请立即轮换。不要在公开代码仓库或日志中明文保存。": "All tokens are generated locally in your browser and never travel over the network or get stored on a server. Please keep generated secrets safe and rotate them immediately if leaked. Never store them in plaintext in public code repositories or logs.",
 "各格式适用场景：": "When to use each format:",
 "（十六进制）：兼容性最好，可直接存入数据库或打印在日志，但长度是原始字节的 2 倍，适合用作随机盐值、设备指纹。": " (hexadecimal): best compatibility, can be stored directly in a database or printed in logs, but twice the length of the raw bytes; suitable as a random salt or device fingerprint.",
 "：体积比 Hex 小约 1/3，常用于配置文件或网络传输，但不适合直接放进 URL。": ": about 1/3 smaller than Hex, commonly used in config files or network transmission, but not suitable for direct use in URLs.",
 "：将": ": replaces ",
 "和": " and ",
 "，并去掉末尾填充": ", and removes the trailing padding ",
 "，专用于 URL、JWT 载荷或文件名，不会被转义。": ", made for URLs, JWT payloads or file names, and will not be escaped.",
 "Hex、Base64 和 Base64URL 该怎么选？": "How do I choose between Hex, Base64 and Base64URL?",
 "Hex（十六进制）兼容性好、可直接用于数据库或日志，但体积比原始字节大 1 倍；Base64 体积更小，常用于配置或传输；Base64URL 把 + 和 / 替换为 - 和 _，并去掉填充 =，适合放在 URL、JWT 或文件名中，避免被转义。": "Hex (hexadecimal) has good compatibility and can be used directly in databases or logs, but is twice the size of the raw bytes; Base64 is smaller and commonly used for configuration or transmission; Base64URL replaces + and / with - and _ and drops the = padding, making it suitable for URLs, JWTs or file names without escaping.",
 "生成的 Token 安全吗？": "Are the generated tokens secure?",
 "本工具使用浏览器内置的 crypto.getRandomValues 密码学安全随机数生成器生成，不可被预测。所有内容仅在本地生成，不会上传。生成后请妥善保存，密钥一旦泄露应立刻轮换。": "This tool uses the browser built-in cryptographically secure random number generator crypto.getRandomValues, so the output cannot be predicted. Everything is generated locally and never uploaded. Please keep the results safe and rotate keys immediately if they are leaked.",
 "Token 需要多长才安全？": "How long does a token need to be to be secure?",
 "用于会话令牌或 API Key 推荐至少 32 字节（256 位）的随机熵；短期或低敏感场景 16 字节也可接受。输出长度越长，暴力破解难度越高。请避免重复使用同一 Token 用于不同用途。": "For session tokens or API keys, at least 32 bytes (256 bits) of random entropy is recommended; 16 bytes is acceptable for short-term or low-sensitivity scenarios. Longer output means a harder brute-force attack. Please avoid reusing the same token for different purposes.",
 "在线 Token 生成器，使用 crypto 安全随机数生成随机令牌、密钥与 API Key，支持多格式与批量生成。": "Online token generator using crypto secure random numbers to generate random tokens, secrets and API keys, with multiple formats and batch generation.",
